function renderReelsV15GenerationSources(){
  const wrap=document.getElementById('reelsV15SourceChips');
  if(!wrap)return;
  const selected=new Set(
    [...wrap.querySelectorAll('[data-reels-v15-source].active')]
      .map(btn=>String(btn.dataset.reelsV15Source||''))
      .filter(Boolean)
  );
  if(!selected.size)selected.add('stranger');

  const actors=(typeof getRelationshipActors==='function'?getRelationshipActors():[])
    .filter(actor=>actor && (actor.kind==='roche'||actor.kind==='npc'));

  wrap.innerHTML=[
    `<button class="reels-v15-chip ${selected.has('stranger')?'active':''}" data-reels-v15-source="stranger" type="button">陌生人</button>`,
    ...actors.map(actor=>`
      <button class="reels-v15-chip ${selected.has(actor.id)?'active':''}" data-reels-v15-source="${escapeDMCardHTML(actor.id)}" type="button">
        ${escapeDMCardHTML(actor.name)}
      </button>`)
  ].join('');
}

function getSelectedReelsV15Sources(){
  return [...document.querySelectorAll('#reelsV15SourceChips [data-reels-v15-source].active')]
    .map(btn=>String(btn.dataset.reelsV15Source||''))
    .filter(Boolean);
}

async function runINSReelsGeneration(){
  const btn=document.getElementById('reelsV15GenerateConfirm');
  if(btn?.disabled)return;

  const selected=getSelectedReelsV15Sources();
  if(!selected.length){
    alert('至少选择一个已有角色 / NPC，或选择“陌生人”');
    return;
  }

  const prompt=document.getElementById('reelsV15BatchPrompt')?.value.trim()||'';
  const wantStranger=selected.includes('stranger');
  const formal=selected
    .filter(id=>id!=='stranger')
    .map(normalizeSocialActorId)
    .filter(id=>isFormalSocialActor(id)&&id!=='user');

  setINSGenerationButtonBusy(btn,true,'生成中…');

  try{
    const made=[];
    const commentJobs=[];

    if(formal.length){
      const ownerId=formal.length===1?formal[0]:'user';
      const result=await callNiniINSAI(INS_AI_TASKS.REELS_GENERATE,{
        actorIds:formal,
        ownerId,
        surface:'reels',
        prompt:composeCharGenerationPrompt({actorIds:formal,surface:'reels',batchPrompt:prompt,extraPrompt:buildINSActorLocationPrompt(formal)}),
        extra:{
          requestedCount:formal.length,
          onePerActor:true,
          includeInitialComments:true,
          initialCommentCount:5,
          diagnosticBuild:'5.0.5-reels'
        }
      });
      if(!result.ok)throw new Error(result.reason||'角色 Reels 生成失败');

      const rows=getGeneratedItems(result.data);
      rows.forEach((row,index)=>{
        const actorId=resolveGeneratedActorId(row,formal,index);
        if(!actorId||!formal.includes(actorId))return;
        const actor=getRelationshipActor(actorId);
        const kind=actor?.kind==='npc'?'npc':'char';
        const item=makeGeneratedReelItem(row,actorId,kind,index);
        made.push(item);
        recordGeneratedReelPublish(actorId,item);

        const initialComments=Array.isArray(row?.initialComments)?row.initialComments:[];
        if(initialComments.length){
          commentJobs.push({contentId:item.id,ownerId:actorId,comments:initialComments});
        }
      });
    }

    if(wantStranger){
      const result=await callNiniINSAI(INS_AI_TASKS.REELS_GENERATE,{
        actorIds:[],
        ownerId:'',
        surface:'reels',
        prompt,
        extra:{
          requestedCount:1,
          generateStrangers:true,
          strangerCount:1,
          includeInitialComments:true,
          initialCommentCount:5,
          diagnosticBuild:'5.0.5-reels-stranger'
        }
      });
      if(!result.ok)throw new Error(result.reason||'陌生人 Reels 生成失败');

      const rows=getGeneratedItems(result.data).slice(0,1);
      rows.forEach((row,index)=>{
        const handle=registerGeneratedPublicIdentity(row,index);
        const item=makeGeneratedReelItem(row,handle,'stranger',formal.length+index);
        made.push(item);
        recordGeneratedReelPublish(handle,item,{knownByUser:true});

        const initialComments=Array.isArray(row?.initialComments)?row.initialComments:[];
        if(initialComments.length){
          commentJobs.push({contentId:item.id,ownerId:handle,comments:initialComments});
        }
      });
    }

    if(!made.length)throw new Error('AI 没有返回可用的 Reel items');

    reelsV15State.items.unshift(...made);
    reelsV15State.activeId=made[0].id;

    commentJobs.forEach(job=>{
      applyGeneratedPublicCommentBatch({
        surface:'reels',
        contentId:job.contentId,
        ownerId:job.ownerId,
        comments:job.comments
      });
    });
    made.forEach(item=>{
      queueMicrotask(()=>void ensurePublicCommentFloor('reels',item.id,5).then(()=>scheduleINSReelsPersistence()).catch(err=>console.warn('[INS] Reel initial comment top-up failed',err)));
    });

    scheduleINSReelsPersistence();
    renderReelsV15();
    closeReelsV15Sheets();
    showReelsV15Toast(`已生成 ${made.length} 条 Reel`);
  }catch(error){
    alert('生成 Reel 失败（v5.0.5）\n\n'+(error?.message||error));
  }finally{
    setINSGenerationButtonBusy(btn,false,'','生成 Reel');
  }
}

