document.getElementById('reelsV15CommentSend')?.addEventListener('click',()=>{
  const item=getActiveReelsV15Item();
  const input=document.getElementById('reelsV15CommentInput');
  const text=input?.value.trim();
  if(!item||!text)return;
  if(!reelsV15State.comments[item.id])reelsV15State.comments[item.id]=[];
  ensurePublicCommentThreadIds(reelsV15State.comments[item.id],`reel_${item.id}`);

  const replyTarget=reelsV15CommentReplyTo&&typeof reelsV15CommentReplyTo==='object'?reelsV15CommentReplyTo:null;
  const replyId=normalizeSocialActorId(replyTarget?.author||'');
  reelsV15State.comments[item.id].push({
    commentId:makePublicCommentId(`reel_${item.id}`),
    initial:'U',
    author:'user',
    text,
    translation:'',
    replyToCommentId:String(replyTarget?.commentId||''),
    replyToActorId:replyId,
    generated:false,
    createdAt:Date.now()
  });
  item.comments+=1;

  if(typeof recordSocialEvent==='function'){
    const ownerId=normalizeSocialActorId(item.author);
    const known=['user'];
    if(isFormalSocialActor(ownerId))known.push(ownerId);
    if(replyId&&isFormalSocialActor(replyId))known.push(replyId);

    recordSocialEvent({
      type:'reel_comment',
      actorId:'user',
      targetIds:known.filter(id=>id!=='user'),
      contentId:item.id,
      contentType:'reel',
      contentOwnerId:ownerId,
      threadId:`reel_comments:${item.id}`,
      replyToActorId:replyId,
      text,
      visibility:'public',
      payload:{replyToCommentId:String(replyTarget?.commentId||'')},
      summary:`${socialActorName('user')}在 ${socialActorName(ownerId)} 的 Reel 下${replyId?`回复了 ${socialActorName(replyId)}`:'评论'}：“${text}”`
    },{knownActorIds:known,learnedVia:'direct_comment'});
  }

  input.value='';
  input.placeholder='添加评论…';
  reelsV15CommentReplyTo=null;
  renderReelsV15Comments();
  renderReelsV15();
  scheduleINSReelsPersistence();
});

