function dmCloseCards(){
  document.getElementById('dmChatDim')?.classList.remove('show');
  document.getElementById('dmEmojiCard')?.classList.remove('show');
  document.getElementById('dmChatMenuCard')?.classList.remove('show');
  document.getElementById('dmClearConfirmCard')?.classList.remove('show');
}
function dmOpenCard(id){
  dmCloseCards();
  document.getElementById('dmChatDim')?.classList.add('show');
  document.getElementById(id)?.classList.add('show');
}

function getDMListRow(recipient){
  return document.querySelector(`#dmV2List [data-dm-chat="${CSS.escape(recipient||'')}"]`);
}
function formatDMListPreviewMessage(row){
  if(!row)return '暂无消息';
  if(row.from==='photo') return '照片';
  return row.text || '暂无消息';
}
function updateDMListPreview(recipient, customText=''){
  const row=getDMListRow(recipient);
  if(!row)return;
  const preview=row.querySelector('.dm-v2-preview');
  const time=row.querySelector('.dm-v2-time');

  let text=customText;
  if(!text){
    const messages=dmBaseMessages[recipient]||[];
    text=formatDMListPreviewMessage(messages.at(-1));
  }

  if(preview)preview.textContent=text || '暂无消息';
  if(time)time.textContent='刚刚';
}
function syncAllDMListPreviews(){
  Object.keys(dmBaseMessages).forEach(recipient=>updateDMListPreview(recipient));
}

function addDMMessage(recipient, from, text, translation='', meta={}){
  if(!recipient)return;
  if(!dmBaseMessages[recipient])dmBaseMessages[recipient]=[];
  const createdAt=Date.now();
  const normalizedText=typeof text==='object'?String(text.text||text.textOriginal||''):String(text||'');
  const normalizedTranslation=typeof text==='object'?String(text.translation||text.textTranslation||''):String(translation||'');
  const messageRow={
    from,text:normalizedText,translation:normalizedTranslation,translated:false,createdAt,
    _uiId:`dm_${recipient}_${createdAt}_${Math.random().toString(36).slice(2,5)}`,
    _memoryEventId:'',
    _replyRoundId:String(meta?.replyRoundId||''),
    _replyRoundFirst:!!meta?.replyRoundFirst
  };
  dmBaseMessages[recipient].push(messageRow);

  if(typeof recordSocialEvent==='function' && normalizedText){
    const recipientId=normalizeSocialActorId(recipient);
    const actorId=from==='them'?recipientId:'user';
    const targetId=from==='them'?'user':recipientId;
    if(isFormalSocialActor(actorId)&&isFormalSocialActor(targetId)){
      const event=recordSocialEvent({type:'dm_message',actorId,targetIds:[targetId],contentId:`dm:${recipientId}`,contentType:'dm',text:normalizedText,visibility:'private',createdAt,dedupeKey:`dm_message:${messageRow._uiId}`,summary:`${socialActorName(actorId)}在 INS 私信里对 ${socialActorName(targetId)} 说：“${compactMemoryText(normalizedText,120)}”`},{knownActorIds:[actorId,targetId],learnedVia:'dm_message'});
      if(event?.eventId)messageRow._memoryEventId=event.eventId;
    }
  }

  scheduleINSDMHistoryPersistence();
  updateDMListPreview(recipient);
  renderDMChatStream(recipient);
  if(from==='them'&&normalizedText&&isFormalSocialActor(recipient))pushINSNotification({actorId:recipient,type:'dm',copy:'发来了一条新私信'});
}

function dmSendInput(){
  const input = document.getElementById('dmMsgInput');
  const text = input?.value.trim() || '';
  if(!text) return;
  addDMMessage(currentDMChat, 'me', text);
  input.value = '';
}
