function waitDMSharePendingV122(ms=520){return new Promise(resolve=>setTimeout(resolve,ms));}

async function dmSummonAI(options={}){
  if(!currentDMChat||dmAIReplyInFlight)return;
  const typing=document.getElementById('dmTyping');
  const plane=document.getElementById('dmAIPlaneBtn');
  const profile=getDMProfile(currentDMChat);
  const typingAvatar=typing?.querySelector('.dm-msg-avatar');
  const replyRoundId=`dmround_${Date.now()}_${Math.random().toString(36).slice(2,7)}`;
  dmAIReplyInFlight=true;
  if(plane){plane.disabled=true;plane.setAttribute('aria-busy','true');}
  if(typingAvatar){
    typingAvatar.textContent=profile.avatarUrl?'':profile.initial;
    typingAvatar.style.backgroundImage=profile.avatarUrl?`url("${profile.avatarUrl}")`:'';
    typingAvatar.style.backgroundSize=profile.avatarUrl?'cover':'';
    typingAvatar.style.backgroundPosition=profile.avatarUrl?'center':'';
  }
  typing?.classList.add('show');
  requestAnimationFrame(()=>{const scroller=document.getElementById('dmChatScroll');if(scroller)scroller.scrollTop=scroller.scrollHeight;});
  try{
    const actorId=normalizeSocialActorId(currentDMChat);
    const recent=(dmBaseMessages[currentDMChat]||[]).slice(-18).map(row=>({
      id:row._uiId||'',from:row.from,text:row.text,translation:row.translation||'',createdAt:Number(row.createdAt)||0
    }));
    const shareState=dmShareIntentState[actorId]||{pending:0};
    const shareCandidates=getDMShareCandidates(actorId,12);
    const result=await callNiniINSAI(INS_AI_TASKS.DM_REPLY,{
      actorIds:actorId?[actorId]:[],
      ownerId:actorId,
      surface:'dm',
      content:{
        recentMessages:recent,
        sharedCards:(dmSharedCards[currentDMChat]||[]).slice(-4),
        socialContext:typeof getDMModelContext==='function'?getDMModelContext(actorId,8):[],
        dmShare:{
          pendingInterest:Number(shareState.pending)||0,
          candidates:shareCandidates,
          policy:[
            'Sharing is a semantic decision, not a keyword rule. Read the whole recent conversation and the actor personality.',
            'If User casually asks for something funny, interesting, cute, weird, pretty, or something the actor thinks User would enjoy, normally create a NEW dm_only card directly in this same dm_reply output. Do not route that generic request through known-content candidates.',
            'Use linked only when the conversation clearly points to one specific existing/previously-known post or Reel. own_publish is only when the actor genuinely decides to publish publicly first.',
            'For generic requests, Feed versus Reel is flexible. Prefer Reel when the request is clearly about video/motion; prefer Feed when it is clearly about photos/images; otherwise either is fine. Do not hard-lock the type from a single word if the overall meaning says otherwise.',
            'If sharing, return share.decision=share plus a complete valid card payload in this same response. Do not rely on stock phrases such as “here/给你看这个” as a trigger and do not require a second generation call.',
            'A dm_only share may reflect the actor taste, what they think User would like, or a subtle personality-consistent hint; it must still feel like something this actor would naturally choose.',
            'Never share Story.'
          ].join(' ')
        },
        reroll:!!options?.reroll
      }
    });
    if(!result.ok)throw new Error(result.reason||'AI 回复失败');

    const rawRows=Array.isArray(result.data?.messages)?result.data.messages:(result.data?.reply?[result.data.reply]:[]);
    const replyRows=rawRows.slice(0,4).map(row=>({
      text:String(row?.textOriginal??row?.text??'').trim(),
      translation:String(row?.textTranslation??row?.translation??'').trim()
    })).filter(row=>row.text);
    const share=extractDMShareDecision(result.data,rawRows);
    const willAttemptShare=shouldAttemptDMShareCardV122(share);
    if(willAttemptShare){
      showDMSharePendingBubbleV122(currentDMChat);
      await waitDMSharePendingV122();
    }
    const didShare=applyActorDMShareDecision(actorId,share,false,{replyRoundId});
    removeDMSharePendingBubbleV122();
    if(willAttemptShare&&!didShare)throw new Error('AI 返回了分享决定，但分享卡片结构无效');

    replyRows.forEach((row,index)=>{
      addDMMessage(currentDMChat,'them',row.text,row.translation,{
        replyRoundId,
        replyRoundFirst:index===0
      });
    });
    if(!replyRows.length&&!didShare)throw new Error('AI 没有返回 messages 或 share');
  }catch(error){
    alert('INS 私信 AI 调用失败：'+(error?.message||error));
  }finally{
    removeDMSharePendingBubbleV122();
    typing?.classList.remove('show');
    if(plane){plane.disabled=false;plane.removeAttribute('aria-busy');}
    dmAIReplyInFlight=false;
  }
}

