/* ===== Navigation skeleton router ===== */
const routeStack = [];
let currentCharProfile = null;
let currentDMChat = null;

function getVisibleRoute(){
  return [...document.querySelectorAll('.route-page.show')].pop() || null;
}

function showRoute(id){
  const next = document.getElementById(id);
  if(!next) return;

  const current = getVisibleRoute();
  if(current && current.id === id) return;

  if(current){
    routeStack.push(current.id);
    current.classList.remove('show');
  }

  // Defensive cleanup: never allow two route overlays to cover each other.
  document.querySelectorAll('.route-page.show').forEach(el=>el.classList.remove('show'));
  next.classList.add('show');
}

function hideRoute(id){
  const el = document.getElementById(id);
  if(el) el.classList.remove('show');
}

function backRoute(){
  const current = getVisibleRoute();
  if(current) current.classList.remove('show');

  let prev = routeStack.pop();
  while(prev && !document.getElementById(prev)){
    prev = routeStack.pop();
  }

  if(prev){
    document.getElementById(prev)?.classList.add('show');
  }
}


/* ===== v5.0.8 overlay hygiene: stale editor/dim layers must never block taps ===== */
function clearProfileInteractionOverlays(){
  [
    'profileDrawerDim','profileDrawer','profileEditCard','highlightEditorCard',
    'profileAtmosphereCard','profileImagePromptCard','profileFeedTranslationApiCard','memorySystemCard',
    'charDrawerDim','charDrawer','charHighlightEditor','charProfileEditor'
  ].forEach(id=>document.getElementById(id)?.classList.remove('show'));
}

function clearTransientProfileRoutes(){
  clearProfileInteractionOverlays();
  document.getElementById('profileContentDetailRoute')?.classList.remove('show');
  document.getElementById('niniHighlightViewer')?.classList.remove('show');
}

const storySeenState = {};

function canCurrentUserViewStory(owner){
  const ownerId=normalizeSocialActorId(owner);
  if(!ownerId || ownerId==='user')return true;
  const actor=typeof getRelationshipActor==='function'?getRelationshipActor(ownerId):null;
  if(!actor || !['roche','npc'].includes(actor.kind))return false;
  const partners=typeof getDirectRelationshipPartners==='function'?getDirectRelationshipPartners(ownerId):[];
  return partners.map(normalizeSocialActorId).includes('user');
}
function canStoryRecipientReceiveFromOwner(owner,recipient){
  const ownerId=normalizeSocialActorId(owner);
  const recipientId=normalizeSocialActorId(recipient);
  if(!ownerId || !recipientId || ownerId===recipientId)return false;
  const recipientActor=typeof getRelationshipActor==='function'?getRelationshipActor(recipientId):null;
  if(ownerId==='user')return !!recipientActor && ['roche','npc'].includes(recipientActor.kind);
  if(!recipientActor || !['user','roche','npc'].includes(recipientActor.kind))return false;
  const partners=typeof getDirectRelationshipPartners==='function'?getDirectRelationshipPartners(ownerId):[];
  return partners.map(normalizeSocialActorId).includes(recipientId);
}

function syncHomeStoryStrip(options={}){
  if(!options.skipExpiry)expireLiveStoriesNow({render:false});
  const container=document.querySelector('.stories');
  if(!container)return;

  [...container.querySelectorAll('.story:not(.user)')].forEach(el=>el.remove());

  const actors=(typeof getRelationshipActors==='function'?getRelationshipActors():[])
    .filter(actor=>actor && (actor.kind==='roche'||actor.kind==='npc'));

  actors.forEach(actor=>{
    const items=storyViewerData[actor.id]||[];
    if(!items.length || !canCurrentUserViewStory(actor.id))return;

    const item=document.createElement('div');
    item.className='story'+(storySeenState[actor.id]?' seen':'');
    item.innerHTML=`
      <div class="story-wrap" data-story-owner="${escapeRocheHydrationHTML(actor.id)}">
        <div class="story-ring"><div class="story-inner">
          ${actor.avatarUrl
            ? `<img src="${escapeRocheHydrationHTML(actor.avatarUrl)}" alt="">`
            : `<div style="width:100%;height:100%;display:grid;place-items:center;font-weight:800">${escapeRocheHydrationHTML(actor.initial||'?')}</div>`}
        </div></div>
      </div>
      <div class="story-name">${escapeRocheHydrationHTML(actor.name||actor.handle||actor.id)}</div>`;
    item.querySelector('[data-story-owner]')?.addEventListener('click',()=>openStory(actor.id));
    container.appendChild(item);
  });

  sortStoryStrip();
}

function sortStoryStrip(){
  const container = document.querySelector('.stories');
  if(!container) return;

  const userStory = container.querySelector('.story.user');
  const charStories = [...container.querySelectorAll('.story:not(.user)')];

  // unread colored rings first; viewed gray rings after them.
  charStories.sort((a,b)=>{
    return Number(a.classList.contains('seen')) - Number(b.classList.contains('seen'));
  });

  const frag = document.createDocumentFragment();
  if(userStory) frag.appendChild(userStory);
  charStories.forEach(el=>frag.appendChild(el));
  container.appendChild(frag);
}

function markStorySeen(owner){
  if(owner === 'user') return;
  storySeenState[owner]=true;

  const wrap = document.querySelector(`[data-story-owner="${owner}"]`);
  const story = wrap?.closest('.story');
  if(story){
    story.classList.add('seen');
    sortStoryStrip();
  }

  if(typeof recordSocialEvent==='function'){
    const ownerId=normalizeSocialActorId(owner);
    if(isFormalSocialActor(ownerId)){
      const contentId=currentStoryMemoryContentId(owner);
      recordSocialEvent({
        type:'story_view',
        actorId:'user',
        targetIds:[ownerId],
        contentId,
        contentType:'story',
        contentOwnerId:ownerId,
        visibility:'private',
        dedupeKey:`story_view:user:${ownerId}:${contentId}`,
        summary:`${socialActorName('user')}看了 ${socialActorName(ownerId)} 的 Story。`
      },{knownActorIds:['user',ownerId],learnedVia:'story_viewer'});
    }
  }
}

/* ===== v1.15.18 reaction semantics =====
   Stable semantic code first; emoji is presentation only.
   Later emoji can be replaced without rewriting Social Events / memory.
*/
const INS_REACTION_SCHEMA = {
  like:{code:'like',emoji:'❤️',label:'看到了 / 喜欢',promptMeaning:'看到了这条 Story，顺手表达喜欢或轻度认可'},
  amused:{code:'amused',emoji:'🤣',label:'笑疯了',promptMeaning:'真的被逗笑，觉得非常好笑或很有梗'},
  excited:{code:'excited',emoji:'🔥',label:'太赞了',promptMeaning:'觉得很酷、很赞、有冲击力或明显兴奋'},
  affectionate:{code:'affectionate',emoji:'🥰',label:'好喜欢 / 好可爱',promptMeaning:'觉得可爱、喜欢、温柔或很有好感'},
  shocked:{code:'shocked',emoji:'😱',label:'吓到 / 震惊',promptMeaning:'强烈惊讶、被吓到或没想到会看到这样的内容'},
  supportive:{code:'supportive',emoji:'👏',label:'赞赏 / 支持',promptMeaning:'赞赏、支持、为对方开心或给予肯定'},
  mindblown:{code:'mindblown',emoji:'🤯',label:'太炸了',promptMeaning:'觉得非常震撼、不可思议或超出预期'},
  emotional:{code:'emotional',emoji:'😭',label:'被戳中了',promptMeaning:'情绪反应很强，可能是感动、共鸣或夸张式被戳中'},
  flustered:{code:'flustered',emoji:'🥵',label:'太绝了 / 顶不住',promptMeaning:'因为内容很有吸引力、很强烈或太绝而产生夸张式反应'}
};
const INS_REACTION_BY_EMOJI = Object.fromEntries(Object.values(INS_REACTION_SCHEMA).map(item=>[item.emoji,item]));
const STORY_REACTION_MEANINGS = Object.fromEntries(Object.values(INS_REACTION_SCHEMA).map(item=>[item.emoji,item.label+' · '+item.promptMeaning]));
function getINSReactionDescriptor(input){
  const raw=String(input||'').trim();
  if(INS_REACTION_SCHEMA[raw])return INS_REACTION_SCHEMA[raw];
  if(INS_REACTION_BY_EMOJI[raw])return INS_REACTION_BY_EMOJI[raw];
  return {code:'custom',emoji:raw||'🙂',label:'自定义表态',promptMeaning:'对这条内容做出了一个自定义情绪表态'};
}
function normalizeINSReactionDecision(data={}){
  const descriptor=getINSReactionDescriptor(data.reactionCode||data.code||data.emoji);
  return {
    react:data.react!==false,
    reactionCode:descriptor.code,
    emoji:data.emoji||descriptor.emoji,
    attitudeSummary:String(data.attitudeSummary||data.attitude||descriptor.promptMeaning).trim(),
    displayLabel:descriptor.label
  };
}

const storyViewerData = {user:[]};

Object.values(storyViewerData).forEach(items=>{
  items.forEach(item=>{
    if(typeof item.liked==='undefined') item.liked=false;
    if(typeof item.linkedAlbumId==='undefined') item.linkedAlbumId='';
    if(typeof item.generated==='undefined') item.generated=false;
  });
});

/* Story generation contract:
   one Story batch contains 1..4 items, not always 4.
   Each item independently chooses image or video. */
function normalizeGeneratedStoryItems(items){
  const safe=(Array.isArray(items)?items:[]).slice(0,4);
  return safe.length ? safe : [{id:'story_auto_'+Date.now(),type:'image',time:'刚刚',description:'Story 内容占位',liked:false}];
}

const INS_CONTENT_GENERATION_CONTRACT = {
  feed:{
    media:'image_or_video_description',
    caption:'required',
    translation:'on_demand_separate_user_api_not_in_generation',
    metrics:'likes_comments_reposts_shares_in_same_result',
    initialComments:'same_call_optional_batch_from_relationship_eligible_actors_and_strangers'
  },
  story:{
    items:'1_to_4_image_or_video',
    caption:'one_caption_for_whole_batch',
    translation:'same_call_separate_field_when_foreign',
    comments:'none',
    reactions:'semantic_reaction_code_then_ui_emoji'
  },
  reels:{
    media:'video_description',
    caption:'required',
    translation:'same_call_separate_field_when_foreign',
    metrics:'likes_comments_reposts_in_same_result',
    initialComments:'same_call_optional_batch_from_relationship_eligible_actors_and_strangers'
  }
};

