/* Media understanding policy:
   1) Manual description wins and skips vision.
   2) If image description is empty, use cached visionSummary.
   3) If both are empty, mark a one-time vision analysis as needed.
   Formal Roche integration should write a short summary back to visionSummary,
   then reuse it instead of re-sending the image on every model call. */
function getImageSemanticContext(item){
  if(!item || item.type!=='image') return {source:'none',text:''};

  const manual=(item.description||'').trim();
  if(manual) return {source:'manual',text:manual};

  const cached=(item.visionSummary||'').trim();
  if(cached) return {source:'vision_cache',text:cached};

  if(item.mediaUrl){
    return {
      source:'vision_needed',
      text:'',
      imageUrl:item.mediaUrl,
      instruction:'仅生成简短客观图片摘要，用于后续社交上下文缓存，不需要重复分析。'
    };
  }

  return {source:'none',text:''};
}
function cacheImageVisionSummary(item,summary){
  if(!item || item.type!=='image')return;
  item.visionSummary=(summary||'').trim();
  item.visionStatus=item.visionSummary?'ready':'idle';
}
function resolveStoryMediaContextForModel(owner){
  return (storyViewerData[owner]||[]).map(item=>{
    if(item.type==='video'){
      return {id:item.id,type:'video',text:(item.description||'').trim(),source:'manual'};
    }
    const semantic=getImageSemanticContext(item);
    return {id:item.id,type:'image',...semantic};
  });
}

function publishUserStory(){
  document.querySelectorAll('[data-story-create-desc]').forEach(el=>{
    const index=Number(el.dataset.storyCreateDesc||0);
    if(storyCreateDraft.items[index]) storyCreateDraft.items[index].description=el.value.trim();
  });

  document.querySelectorAll('[data-story-create-url]').forEach(el=>{
    const index=Number(el.dataset.storyCreateUrl||0);
    const item=storyCreateDraft.items[index];
    if(!item || item.type==='video')return;
    const url=el.value.trim();
    if(url){
      item.mediaUrl=url;
      item.mediaSource='url';
      item.generatedRequested=false;
      item.fileName='';
    }
  });

  const caption=document.getElementById('storyCreateCaption')?.value.trim()||'';

  if(!storyCreateDraft.items.length){
    alert('先添加至少 1 个图片或视频');
    return;
  }

  for(let index=0; index<storyCreateDraft.items.length; index++){
    const item=storyCreateDraft.items[index];

    if(item.type==='video' && !item.description?.trim()){
      alert(`第 ${index+1} 条视频必须填写内容描述`);
      return;
    }

    if(item.type==='image' && !item.mediaUrl && !item.generatedRequested){
      alert(`第 ${index+1} 张图片请选择：上传图片、图片 URL，或者生图`);
      return;
    }

    if(item.type==='image' && item.generatedRequested && !item.description?.trim()){
      alert(`第 ${index+1} 张图片选择了生图，请先写生图描述`);
      return;
    }
  }

  storyViewerData.user=storyCreateDraft.items.slice(0,4).map((item,index)=>({
    ...item,
    id:item.id || ('story_user_'+Date.now()+'_'+index),
    description:(item.description||'').trim(),
    liked:false,
    linkedAlbumId:'',
    generated:!!item.generatedRequested,
    visionSummary:item.visionSummary||'',
    visionStatus:item.visionSummary?'ready':'idle'
  }));

  const batchState=getStoryBatchState('user');
  batchState.caption=caption;
  batchState.liked=false;
  batchState.audienceReactions=[];

  // One publish = one whole Story batch in archive; live copy expires separately.
  const publishedStoryRecord=archivePublishedStoryBatch('user', storyViewerData.user, caption);
  markStoryBatchLive('user',publishedStoryRecord);
  resetUserStoryAudiencePlan('publish');

  storyViewerState.owner='user';
  storyViewerState.index=0;

  // Publishing is complete: return directly to Feed.
  hideRoute('routeStoryCreate');
  hideRoute('routeStory');
  routeStack.length=0;
  state.active='home';
  renderNav();
  queueMicrotask(()=>void ensureStoryAudienceReactionPlan({trigger:'publish',silent:true}));
}


