/* This is deterministic metadata only, not an AI Story-summary call.
   Full batch summarization for DM/Highlight is intentionally deferred. */
function compactStoryMediaUnderstanding(owner){
  const rows=resolveStoryMediaContextForModel(owner);
  const manual=rows.filter(x=>x.source==='manual').length;
  const cached=rows.filter(x=>x.source==='vision_cache').length;
  const pending=rows.filter(x=>x.source==='vision_needed').length;
  const parts=[];
  if(manual)parts.push(`${manual}条人工描述`);
  if(cached)parts.push(`${cached}条识图缓存`);
  if(pending)parts.push(`${pending}张待按需识图`);
  return parts.join(' · ');
}
function summarizeStoryBatchForShare(owner){
  const items=storyViewerData[owner]||[];
  const imageCount=items.filter(x=>x.type==='image').length;
  const videoCount=items.filter(x=>x.type==='video').length;
  const bits=[];
  if(imageCount)bits.push(`${imageCount}张图片`);
  if(videoCount)bits.push(`${videoCount}个视频`);
  return `${items.length}条 · ${bits.join(' + ') || 'Story'}`;
}
function sendStoryBatchToDM(recipient){
  const owner=storyViewerState.owner;
  if(!owner || !recipient || !canStoryRecipientReceiveFromOwner(owner,recipient))return;
  const state=getStoryBatchState(owner);
  if(!dmSharedCards[recipient])dmSharedCards[recipient]=[];
  dmSharedCards[recipient].push(makeDMContextCard('story_share',{
    author:owner==='user'?userProfileState.id:owner,
    caption:state.caption||'',
    mediaDescription:summarizeStoryBatchForShare(owner),
    contextSummary:`user 分享了 @${owner==='user'?userProfileState.id:owner} 的一组 Story。文案：${compactDMContextText(state.caption||'无',90)}。内容：${summarizeStoryBatchForShare(owner)}。`
  }));
  scheduleINSDMHistoryPersistence();
  updateDMListPreview(recipient,'分享了一组 Story');

  if(typeof recordSocialEvent==='function'){
    const recipientId=normalizeSocialActorId(recipient);
    const ownerId=normalizeSocialActorId(owner);
    recordSocialEvent({
      type:'dm_share_content',
      actorId:'user',
      targetIds:[recipientId],
      contentId:currentStoryMemoryContentId(owner),
      contentType:'story',
      contentOwnerId:ownerId,
      visibility:'private',
      payload:{
        sharedType:'Story',
        sharedOwnerId:ownerId,
        sharedOwnerLabel:owner==='user'?(userProfileState.displayName||userProfileState.id):owner,
        caption:state.caption||'',
        sharedSummary:summarizeStoryBatchForShare(owner)
      },
      summary:`${socialActorName('user')}在 DM 给 ${socialActorName(recipientId)} 分享了 ${socialActorName(ownerId)} 的 Story。`
    },{knownActorIds:['user',recipientId],learnedVia:'dm_share'});
    if(isFormalSocialActor(recipientId))exposePublicContentToActor(recipientId,currentStoryMemoryContentId(owner),'dm_share');
  }

  closeStorySheets();
  const toast=document.getElementById('storyReactionToast');
  if(toast){
    toast.textContent='已分享到 DM';
    toast.classList.add('show');
    clearTimeout(window.__storyShareToastTimer);
    window.__storyShareToastTimer=setTimeout(()=>toast.classList.remove('show'),1000);
  }
}

function sendStoryReaction(emoji){
  const owner=storyViewerState.owner;
  if(!owner || owner==='user')return;

  const items=storyViewerData[owner] || [];
  if(!items.length)return;

  const reaction=normalizeINSReactionDecision({emoji});
  const meaning=reaction.attitudeSummary;
  const batchSummary=getStoryBatchCompactSummary(owner);
  const event={
    type:'story_reaction',
    actor:'user',
    target:owner,
    storyBatchSize:items.length,
    reactionCode:reaction.reactionCode,
    emoji:reaction.emoji,
    attitude:meaning,
    createdAt:Date.now(),
    summary:`user 对 ${owner} 这一组 Story（${batchSummary}）使用 ${emoji}，表示：${meaning}。`
  };
  storyReactionEvents.push(event);

  if(typeof recordSocialEvent==='function'){
    const ownerId=normalizeSocialActorId(owner);
    const contentId=currentStoryMemoryContentId(owner);
    recordSocialEvent({
      type:'story_reaction',
      actorId:'user',
      targetIds:[ownerId],
      contentId,
      contentType:'story',
      contentOwnerId:ownerId,
      emoji:reaction.emoji,
      attitude:meaning,
      visibility:'private',
      payload:{reactionCode:reaction.reactionCode},
      summary:`${socialActorName('user')}对 ${socialActorName(ownerId)} 的 Story 使用 ${reaction.emoji}，表示：${meaning}。`
    },{knownActorIds:['user',ownerId],learnedVia:'story_reaction'});
  }

  if(!dmSharedCards[owner]) dmSharedCards[owner]=[];
  dmSharedCards[owner].push(makeDMContextCard('story_reaction',{
    author:owner,
    emoji:reaction.emoji,
    attitude:meaning,
    storyId:'story_batch:'+owner,
    storyDescription:batchSummary,
    contextSummary:event.summary
  }));
  scheduleINSDMHistoryPersistence();
  if(currentDMChat===owner) renderDMChatStream(owner);

  const toast=document.getElementById('storyReactionToast');
  if(toast){
    toast.textContent=`${reaction.emoji} · ${reaction.displayLabel}`;
    toast.classList.add('show');
    clearTimeout(window.__storyReactionToastTimer);
    window.__storyReactionToastTimer=setTimeout(()=>toast.classList.remove('show'),1100);
  }
}


