/* ===== v1.15.17 INS Social Event Log + Actor Knowledge Ledger =====
   Design:
   1) World event stored exactly once.
   2) Per-actor ledger stores only {eventId, learnedAt, learnedVia}.
   3) Public visibility != actor knowledge.
   4) Sync cursor advances only after an actual Roche write succeeds.
*/
const INS_MEMORY_SYNC_PREFIX='[RocheINSSync]';
const INS_MEMORY_SYNC_LEGACY_PREFIX='[NiniINSSync';
const INS_SOCIAL_MEMORY_STORAGE_KEY='nini-instagram-social-memory-v5';
const INS_MEMORY_BUILD_ID='5.1.4';

function makeINSSocialMemoryBase(){
  return {
    version:3,
    buildId:INS_MEMORY_BUILD_ID,
    events:[],
    knowledge:{},
    syncCursor:{},
    mounts:{},              // legacy v1 writeback mount
    sources:{},             // actorId -> [{conversationId,...}]
    writebackTargets:{},    // actorId -> auto-detected single-chat target
    discoveryPrefs:{},      // actorId -> low | normal | high
    nextSeq:1
  };
}
function loadINSSocialMemoryState(){
  const base=makeINSSocialMemoryBase();
  try{
    const raw=localStorage.getItem(INS_SOCIAL_MEMORY_STORAGE_KEY);
    if(!raw)return base;
    const parsed=JSON.parse(raw)||{};

    // Development/update boundary: a new Nini build starts with a clean Event/Knowledge world,
    // while explicit user memory mounts and discovery preferences survive the update.
    if(String(parsed.buildId||'')!==INS_MEMORY_BUILD_ID){
      const fresh={
        ...base,
        mounts:parsed.mounts&&typeof parsed.mounts==='object'?parsed.mounts:{},
        sources:parsed.sources&&typeof parsed.sources==='object'?parsed.sources:{},
        discoveryPrefs:parsed.discoveryPrefs&&typeof parsed.discoveryPrefs==='object'?parsed.discoveryPrefs:{}
      };
      try{localStorage.setItem(INS_SOCIAL_MEMORY_STORAGE_KEY,JSON.stringify(fresh));}catch(e){}
      return fresh;
    }

    return {
      ...base,
      ...parsed,
      buildId:INS_MEMORY_BUILD_ID,
      events:Array.isArray(parsed.events)?parsed.events:[],
      knowledge:parsed.knowledge&&typeof parsed.knowledge==='object'?parsed.knowledge:{},
      syncCursor:parsed.syncCursor&&typeof parsed.syncCursor==='object'?parsed.syncCursor:{},
      mounts:parsed.mounts&&typeof parsed.mounts==='object'?parsed.mounts:{},
      sources:parsed.sources&&typeof parsed.sources==='object'?parsed.sources:{},
      writebackTargets:parsed.writebackTargets&&typeof parsed.writebackTargets==='object'?parsed.writebackTargets:{},
      discoveryPrefs:parsed.discoveryPrefs&&typeof parsed.discoveryPrefs==='object'?parsed.discoveryPrefs:{},
      nextSeq:Number(parsed.nextSeq)||1
    };
  }catch(e){
    return base;
  }
}

const insSocialMemoryState=loadINSSocialMemoryState();
// v5.0 writeback boundary: only knowledge learned after THIS plugin open belongs
// to the close-time batch. Older unsynced entries are intentionally not folded in.
const insMemorySessionStartedAt=Date.now()-1;

function persistINSSocialMemory(){
  try{
    /* Keep the prototype bounded. The real plugin can move this to Roche storage. */
    if(insSocialMemoryState.events.length>800){
      const keep=insSocialMemoryState.events.slice(-800);
      const keepIds=new Set(keep.map(event=>event.eventId));
      insSocialMemoryState.events=keep;
      Object.keys(insSocialMemoryState.knowledge).forEach(actorId=>{
        insSocialMemoryState.knowledge[actorId]=(
          insSocialMemoryState.knowledge[actorId]||[]
        ).filter(entry=>keepIds.has(entry.eventId));
      });
    }
    localStorage.setItem(
      INS_SOCIAL_MEMORY_STORAGE_KEY,
      JSON.stringify(insSocialMemoryState)
    );
  }catch(e){}
}

function normalizeSocialActorId(ref){
  const raw=String(ref||'').replace(/^@/,'').trim();
  if(!raw)return '';
  if(raw==='user' || raw==='you' || raw===String(userProfileState?.id||''))return 'user';

  const actors=typeof getRelationshipActors==='function' ? getRelationshipActors() : [];
  const found=actors.find(actor=>
    actor.id===raw ||
    actor.handle===raw ||
    actor.name===raw
  );
  return found?.id || raw;
}

function socialActorName(ref){
  const id=normalizeSocialActorId(ref);
  if(id==='user'){
    return userProfileState?.displayName || userProfileState?.id || 'user';
  }
  const actor=typeof getRelationshipActor==='function' ? getRelationshipActor(id) : null;
  return actor?.name || actor?.handle || String(ref||id||'某人');
}

function isFormalSocialActor(ref){
  const id=normalizeSocialActorId(ref);
  if(id==='user')return true;
  return !!(typeof getRelationshipActor==='function' && getRelationshipActor(id));
}

function getActorPublicDiscoveryLevel(actorId){
  const id=normalizeSocialActorId(actorId);
  if(!insSocialMemoryState.discoveryPrefs||typeof insSocialMemoryState.discoveryPrefs!=='object')insSocialMemoryState.discoveryPrefs={};
  const value=String(insSocialMemoryState.discoveryPrefs[id]||'normal');
  return ['low','normal','high'].includes(value)?value:'normal';
}
function setActorPublicDiscoveryLevel(actorId,value='normal'){
  const id=normalizeSocialActorId(actorId);
  if(!id||!isFormalSocialActor(id))return false;
  if(!insSocialMemoryState.discoveryPrefs||typeof insSocialMemoryState.discoveryPrefs!=='object')insSocialMemoryState.discoveryPrefs={};
  insSocialMemoryState.discoveryPrefs[id]=['low','normal','high'].includes(String(value))?String(value):'normal';
  persistINSSocialMemory();
  return true;
}
function detectFormalActorMentions(text='',supplied=[]){
  const body=String(text||'');
  const rows=[];
  const push=(id,strength='explicit',directAt=false)=>{
    const actor=getRelationshipActor(normalizeSocialActorId(id));
    if(!actor||actor.id==='user')return;
    const old=rows.find(x=>x.actorId===actor.id);
    const next={actorId:actor.id,strength,directAt:!!directAt};
    if(!old)rows.push(next);
    else if(directAt||strength==='explicit'){old.directAt=old.directAt||!!directAt;old.strength='explicit';}
  };
  (Array.isArray(supplied)?supplied:[]).forEach(raw=>{
    if(raw&&typeof raw==='object')push(raw.actorId||raw.id||raw.handle,raw.strength||raw.mentionStrength||'explicit',!!raw.directAt);
    else push(raw,'explicit',false);
  });
  (typeof getRelationshipActors==='function'?getRelationshipActors():[]).forEach(actor=>{
    if(!actor||actor.id==='user')return;
    const handle=String(actor.handle||'').replace(/^@/,'').trim();
    const name=String(actor.name||'').trim();
    if(handle){
      const escaped=[...handle].map(ch=>'^$.*+?()[]{}|'.includes(ch)?'\\'+ch:ch).join('');
      if(new RegExp('@'+escaped+'(?:\\b|$)','i').test(body))push(actor.id,'explicit',true);
      else if(handle.length>=3 && body.toLowerCase().includes(handle.toLowerCase()))push(actor.id,'explicit',false);
    }
    if(name.length>=2 && body.includes(name))push(actor.id,'explicit',false);
  });
  return rows;
}
function publicDiscoveryProbability(actorId,strength='explicit'){
  const level=getActorPublicDiscoveryLevel(actorId);
  const multiplier=level==='low'?0.5:level==='high'?1.8:1;
  const base=String(strength)==='contextual'?0.15:0.35;
  return Math.min(0.85,Math.max(0,base*multiplier));
}
function maybeGrantPublicDiscovery(event){
  if(!event||event.visibility!=='public')return;
  const mentionRows=Array.isArray(event.payload?.mentionMeta)?event.payload.mentionMeta:[];
  const related=[...new Set((event.relatedActorIds||[]).map(normalizeSocialActorId).filter(Boolean))];
  related.forEach(actorId=>{
    const actor=getRelationshipActor(actorId);
    if(!actor||actor.kind!=='roche')return;
    const meta=mentionRows.find(row=>normalizeSocialActorId(row?.actorId||row?.id)===actorId)||{};
    const directAt=!!meta.directAt;
    const strength=meta.strength||event.payload?.mentionStrength||'explicit';
    if(directAt){grantActorKnowledge(actorId,event.eventId,'public_mention',Date.now());return;}
    if(Math.random()<publicDiscoveryProbability(actorId,strength))grantActorKnowledge(actorId,event.eventId,'public_discovery',Date.now());
  });
}

function getSocialEvent(eventId){
  return insSocialMemoryState.events.find(event=>event.eventId===eventId) || null;
}

function getActorKnowledgeLedger(actorId){
  const id=normalizeSocialActorId(actorId);
  if(!insSocialMemoryState.knowledge[id])insSocialMemoryState.knowledge[id]=[];
  return insSocialMemoryState.knowledge[id];
}

function grantActorKnowledge(actorId,eventId,learnedVia='direct',learnedAt=Date.now()){
  const id=normalizeSocialActorId(actorId);
  if(!id || !isFormalSocialActor(id) || !getSocialEvent(eventId))return false;

  const ledger=getActorKnowledgeLedger(id);
  if(ledger.some(entry=>entry.eventId===eventId))return false;

  ledger.push({
    eventId,
    learnedAt:Number(learnedAt)||Date.now(),
    learnedVia:learnedVia||'direct'
  });
  persistINSSocialMemory();

  const actor=typeof getRelationshipActor==='function' ? getRelationshipActor(id) : null;
  if(actor?.kind==='roche'){
    queueINSMemoryRealtimeSync(id);
  }
  return true;
}

function recordSocialEvent(data={},options={}){
  const actorId=normalizeSocialActorId(data.actorId || data.actor || '');
  const targetIds=[...(data.targetIds||[])].map(normalizeSocialActorId).filter(Boolean);
  if(data.targetId || data.target){
    const one=normalizeSocialActorId(data.targetId || data.target);
    if(one && !targetIds.includes(one))targetIds.push(one);
  }
  const contentOwnerId=normalizeSocialActorId(data.contentOwnerId||'');
  const replyToActorId=normalizeSocialActorId(data.replyToActorId||'');
  const rawRelated=[...(data.relatedActorIds||data.mentionedActorIds||data.payload?.mentionedActorIds||[])];
  const suppliedRelated=rawRelated.map(item=>item&&typeof item==='object'?item:{actorId:item,strength:data.payload?.mentionStrength||'explicit'});
  const detectedMentions=detectFormalActorMentions(data.text||data.summary||'',suppliedRelated);
  const relatedActorIds=[...new Set(detectedMentions.map(row=>row.actorId).filter(Boolean))];
  const optionKnown=(options.knownActorIds||[]).map(normalizeSocialActorId).filter(Boolean);

  // Pure stranger↔stranger platform chatter stays Content only. It becomes an Event only
  // when a formal actor participates, owns/is targeted by the content, or is explicitly referenced.
  const relevanceRefs=[actorId,...targetIds,contentOwnerId,replyToActorId,...relatedActorIds,...optionKnown].filter(Boolean);
  if(!options.forceEvent && !relevanceRefs.some(isFormalSocialActor))return null;

  const dedupeKey=String(data.dedupeKey||'');
  if(dedupeKey){
    const existing=insSocialMemoryState.events.find(event=>event.dedupeKey===dedupeKey);
    if(existing){
      const known=[actorId,...targetIds,...optionKnown].filter(Boolean);
      [...new Set(known)].forEach(id=>grantActorKnowledge(id,existing.eventId,options.learnedVia||'direct'));
      return existing;
    }
  }

  const now=Number(data.createdAt)||Date.now();
  const seq=insSocialMemoryState.nextSeq++;
  const payload=data.payload&&typeof data.payload==='object'?{...data.payload}:{};
  if(detectedMentions.length)payload.mentionMeta=detectedMentions;
  const event={
    eventId:data.eventId || `evt_${now}_${seq}`,
    type:data.type || 'social_event',
    actorId,
    targetIds:[...new Set(targetIds)],
    relatedActorIds,
    contentId:String(data.contentId||''),
    contentType:String(data.contentType||''),
    contentOwnerId,
    threadId:String(data.threadId||''),
    replyToActorId,
    text:String(data.text||''),
    emoji:String(data.emoji||''),
    attitude:String(data.attitude||''),
    visibility:data.visibility || 'private',
    summary:String(data.summary||''),
    dedupeKey,
    payload,
    createdAt:now
  };

  insSocialMemoryState.events.push(event);
  persistINSSocialMemory();

  const known=[actorId,...event.targetIds,...optionKnown].filter(Boolean);
  [...new Set(known)].forEach(id=>grantActorKnowledge(id,event.eventId,options.learnedVia||'direct',now));
  maybeGrantPublicDiscovery(event);

  if(document.getElementById('routeMemoryBridge')?.classList.contains('show'))renderINSMemoryBridge();
  return event;
}

/* Explicitly grant an already-existing public event to a role that actually saw it. */
function exposeSocialEventToActor(actorId,eventId,via='public_exposure'){
  const event=getSocialEvent(eventId);
  if(!event || event.visibility!=='public')return false;
  const ok=grantActorKnowledge(actorId,eventId,via,Date.now());
  if(ok && document.getElementById('routeMemoryBridge')?.classList.contains('show')){
    renderINSMemoryBridge();
  }
  return ok;
}

/* When a role "scrolls past" a public post/reel later, the browsing engine can call this.
   It grants knowledge for all public events already attached to that content/thread. */
function exposePublicContentToActor(actorId,contentId,via='feed_seen'){
  const id=normalizeSocialActorId(actorId);
  const rows=insSocialMemoryState.events.filter(event=>
    event.visibility==='public' &&
    event.contentId===String(contentId||'')
  );

  let changed=0;
  rows.forEach(event=>{
    if(grantActorKnowledge(id,event.eventId,via,Date.now()))changed++;
  });

  if(changed && document.getElementById('routeMemoryBridge')?.classList.contains('show')){
    renderINSMemoryBridge();
  }
  return changed;
}

function getKnownActorIdsForEvent(eventId){
  const ids=[];
  Object.entries(insSocialMemoryState.knowledge).forEach(([actorId,ledger])=>{
    if((ledger||[]).some(entry=>entry.eventId===eventId))ids.push(actorId);
  });
  return ids;
}

function getActorKnowledgeEntries(actorId,{sinceLearnedAt=0,limit=0}={}){
  const id=normalizeSocialActorId(actorId);
  const ledger=(getActorKnowledgeLedger(id)||[])
    .filter(entry=>Number(entry.learnedAt||0)>Number(sinceLearnedAt||0))
    .map(entry=>({entry,event:getSocialEvent(entry.eventId)}))
    .filter(row=>row.event)
    .sort((a,b)=>a.entry.learnedAt-b.entry.learnedAt);

  return limit>0 ? ledger.slice(0,limit) : ledger;
}

function compactMemoryText(text,max=120){
  const clean=String(text||'').replace(/\s+/g,' ').trim();
  return clean.length>max ? clean.slice(0,max-1)+'…' : clean;
}

function memoryContentLabel(event){
  if(event.contentType==='story')return 'Story';
  if(event.contentType==='reel')return 'Reel';
  if(event.contentType==='feed')return 'IG 动态';
  return '内容';
}

function perspectiveLineForEvent(event,viewerId){
  const viewer=normalizeSocialActorId(viewerId);
  const actor=normalizeSocialActorId(event.actorId);
  const owner=normalizeSocialActorId(event.contentOwnerId);
  const replyTo=normalizeSocialActorId(event.replyToActorId);
  const actorName=socialActorName(actor);
  const ownerName=socialActorName(owner);
  const target=event.targetIds?.[0] || '';
  const targetName=socialActorName(target);
  const text=compactMemoryText(event.text,140);
  const contentLabel=memoryContentLabel(event);

  switch(event.type){
    case 'story_view':
      if(viewer===owner)return `${actorName}看了我的 Story。`;
      if(viewer===actor)return `我看了 ${ownerName} 的 Story。`;
      return `我知道 ${actorName} 看了 ${ownerName} 的 Story。`;

    case 'story_reaction':
      if(viewer===owner){
        return `${actorName}看了我的 Story，并用 ${event.emoji||'表情'} 表态${event.attitude?`（${event.attitude}）`:''}。`;
      }
      if(viewer===actor){
        return `我对 ${ownerName} 的 Story 使用了 ${event.emoji||'表情'}。`;
      }
      return `我看到 ${actorName} 对 ${ownerName} 的 Story 使用了 ${event.emoji||'表情'}。`;

    case 'feed_publish':
    case 'reel_publish': {
      const label=event.type==='reel_publish'?'Reel':'IG 动态';
      const caption=compactMemoryText(event.payload?.caption||event.text||'',140);
      const media=compactMemoryText(
        event.payload?.videoDescription||
        event.payload?.mediaDescription||
        '',
        170
      );
      if(viewer===actor){
        return [
          `我发布了一条 ${label}。`,
          caption?`文案：“${caption}”`:'',
          media?`${label==='Reel'?'视频':'配图'}：${media}`:''
        ].filter(Boolean).join(' ');
      }
      return [
        `${actorName}发布了一条 ${label}。`,
        caption?`文案：“${caption}”`:'',
        media?`${label==='Reel'?'视频':'配图'}：${media}`:''
      ].filter(Boolean).join(' ');
    }

    case 'feed_comment':
    case 'reel_comment': {
      const label=event.type==='reel_comment'?'Reel':'IG 动态';
      if(viewer===actor){
        if(replyTo)return `我在 ${ownerName} 的 ${label} 评论区回复了 ${socialActorName(replyTo)}：“${text}”`;
        return `我评论了 ${ownerName} 的 ${label}：“${text}”`;
      }
      if(replyTo && viewer===replyTo){
        return `${actorName}在 ${ownerName} 的 ${label} 评论区回复了我：“${text}”`;
      }
      if(viewer===owner){
        return `${actorName}在我的 ${label}下${replyTo?'回复了评论':'评论'}：“${text}”`;
      }
      return `我刷到 ${ownerName} 的 ${label}时，看见 ${actorName}${replyTo?`回复了 ${socialActorName(replyTo)}`:'评论'}：“${text}”`;
    }

    case 'dm_share_content': {
      const sharedOwner=socialActorName(event.payload?.sharedOwnerId || event.payload?.sharedOwnerLabel || '');
      const sharedType=event.payload?.sharedType || contentLabel;
      const detail=compactMemoryText(event.payload?.sharedSummary || event.payload?.caption || '',120);
      if(viewer===actor){
        return `我在 INS 私信里给 ${targetName} 分享了 ${sharedOwner} 的 ${sharedType}${detail?`：“${detail}”`:''}。`;
      }
      if(event.targetIds?.includes(viewer)){
        return `${actorName}在 INS 私信里给我分享了 ${sharedOwner} 的 ${sharedType}${detail?`：“${detail}”`:''}。`;
      }
      return `我知道 ${actorName} 给 ${targetName} 分享了 ${sharedOwner} 的 ${sharedType}。`;
    }

    case 'dm_message':
      if(viewer===actor){
        return `我在 INS 私信里对 ${targetName} 说：“${text}”`;
      }
      if(event.targetIds?.includes(viewer)){
        return `${actorName}在 INS 私信里对我说：“${text}”`;
      }
      return `我知道 ${actorName} 和 ${targetName} 在 INS 私信中说到：“${text}”`;

    case 'feed_like':
      if(viewer===owner)return `${actorName}赞了我的 IG 动态。`;
      if(viewer===actor)return `我赞了 ${ownerName} 的 IG 动态。`;
      return `我看到 ${actorName}赞了 ${ownerName} 的 IG 动态。`;

    case 'reel_like':
      if(viewer===owner)return `${actorName}赞了我的 Reel。`;
      if(viewer===actor)return `我赞了 ${ownerName} 的 Reel。`;
      return `我看到 ${actorName}赞了 ${ownerName} 的 Reel。`;

    default:
      if(event.summary)return compactMemoryText(event.summary,180);
      return `${actorName}在 INS 发生了一条 ${event.type} 事件。`;
  }
}

function getActorKnowledgeContext(actorId,limit=12){
  const id=normalizeSocialActorId(actorId);
  const rows=getActorKnowledgeEntries(id);
  const recent=rows.slice(-Math.max(1,limit));
  const seen=new Set();
  const out=[];

  recent.forEach(({event})=>{
    const line=perspectiveLineForEvent(event,id);
    if(!line || seen.has(line))return;
    seen.add(line);
    out.push(line);
  });
  return out;
}

function getActorUnsyncedKnowledge(actorId){
  const id=normalizeSocialActorId(actorId);
  const committedCursor=Number(insSocialMemoryState.syncCursor[id]||0);
  return getActorKnowledgeEntries(id,{sinceLearnedAt:committedCursor});
}

function memorySectionForType(type){
  if(type.startsWith('story_'))return 'Story';
  if(type.startsWith('feed_'))return 'Feed';
  if(type.startsWith('reel_'))return 'Reels';
  if(type.startsWith('dm_'))return 'INS 私信';
  return '其他社交';
}

function getActorMemorySources(actorId){
  const id=normalizeSocialActorId(actorId);
  if(!id)return [];
  if(!Array.isArray(insSocialMemoryState.sources[id]))insSocialMemoryState.sources[id]=[];
  return insSocialMemoryState.sources[id];
}

function normalizeRocheConversation(row={}){
  return {
    conversationId:String(row.conversationId||row.id||''),
    conversationName:String(row.conversationName||row.name||row.title||row.id||''),
    isGroup:!!(row.isGroup||row.type==='group'||row.kind==='group')
  };
}

async function bridgeListConversationsForActor(actorId){
  const bridge=window.NiniINSRocheBridge;
  if(!bridge)return null;
  if(typeof bridge.listConversationsForActor==='function')return await bridge.listConversationsForActor(actorId);
  if(typeof bridge.listConversations==='function')return await bridge.listConversations({memberId:actorId,actorId});
  if(bridge.conversation && typeof bridge.conversation.list==='function')return await bridge.conversation.list({memberId:actorId});
  return null;
}

async function bridgeGetShortTermMemory(args){
  const bridge=window.NiniINSRocheBridge;
  if(!bridge)return [];
  if(typeof bridge.getShortTerm==='function')return await bridge.getShortTerm(args);
  if(bridge.memory && typeof bridge.memory.getShortTerm==='function')return await bridge.memory.getShortTerm(args);
  return [];
}

async function bridgeGetLongTermMemory(args){
  const bridge=window.NiniINSRocheBridge;
  if(!bridge)return null;
  if(typeof bridge.getLongTerm==='function')return await bridge.getLongTerm(args);
  if(bridge.memory && typeof bridge.memory.getLongTerm==='function')return await bridge.memory.getLongTerm(args);
  return null;
}

function getActorWritebackTarget(actorId){
  const id=normalizeSocialActorId(actorId);
  const direct=getActorMemorySources(id).find(source=>source.enabled && !source.isGroup);
  if(!direct)return null;
  return {
    conversationId:String(direct.conversationId),
    conversationName:String(direct.conversationName||direct.conversationId),
    isGroup:false
  };
}

function reconcileActorConversationSettings(actorId,conversations=[]){
  const id=normalizeSocialActorId(actorId);
  if(!id)return [];

  const existing=getActorMemorySources(id);
  const byId=new Map(existing.map(row=>[row.conversationId,row]));
  const normalized=(conversations||[])
    .map(normalizeRocheConversation)
    .filter(row=>row.conversationId);

  const merged=normalized.map(conv=>{
    const prev=byId.get(conv.conversationId);
    return {
      conversationId:conv.conversationId,
      conversationName:conv.conversationName,
      isGroup:conv.isGroup,
      // v5.0.1: discovering a Roche conversation does NOT mount it.
      // The user must explicitly enable each single/group conversation, like Moments.
      enabled:prev?.enabled ?? false,
      shortLimit:Number.isFinite(Number(prev?.shortLimit)) ? Math.max(0,Number(prev.shortLimit)) : 50,
      factLimit:Number.isFinite(Number(prev?.factLimit)) ? Math.max(0,Number(prev.factLimit)) : 0,
      coreEnabled:!!prev?.coreEnabled
    };
  });

  insSocialMemoryState.sources[id]=merged;
  delete insSocialMemoryState.writebackTargets[id];
  persistINSSocialMemory();
  return merged;
}

function withINSMemoryTimeout(promise,ms=8000,label='Roche 会话读取'){
  let timer=0;
  return Promise.race([
    Promise.resolve(promise),
    new Promise((_,reject)=>{
      timer=setTimeout(()=>reject(new Error(`${label}超时（${Math.round(ms/1000)} 秒）`)),ms);
    })
  ]).finally(()=>clearTimeout(timer));
}

async function refreshActorMemoryConversations(actorId){
  const id=normalizeSocialActorId(actorId);
  if(!id)return {ok:false,reason:'actor_missing',conversations:[]};
  try{
    const rows=await withINSMemoryTimeout(
      bridgeListConversationsForActor(id),
      8000,
      'Roche 会话读取'
    );
    if(!Array.isArray(rows)){
      return {ok:false,reason:'bridge_not_connected',conversations:getActorMemorySources(id)};
    }
    const conversations=reconcileActorConversationSettings(id,rows);
    renderINSMemoryBridge();
    return {ok:true,conversations};
  }catch(error){
    return {
      ok:false,
      reason:error?.message||'conversation_list_failed',
      conversations:getActorMemorySources(id)
    };
  }
}

function updateActorMemorySource(actorId,conversationId,patch={}){
  const id=normalizeSocialActorId(actorId);
  const rows=getActorMemorySources(id);
  const row=rows.find(item=>item.conversationId===String(conversationId||''));
  if(!row)return false;

  if('enabled' in patch)row.enabled=!!patch.enabled;
  if('shortLimit' in patch)row.shortLimit=Math.max(0,Math.min(500,Number(patch.shortLimit)||0));
  if('factLimit' in patch)row.factLimit=Math.max(0,Math.min(500,Number(patch.factLimit)||0));
  if('coreEnabled' in patch)row.coreEnabled=!!patch.coreEnabled;

  persistINSSocialMemory();
  return true;
}

/* ===== v1.2.25 request-time Roche memory dedupe =====
   This only deduplicates the text sent into one INS AI request.
   It never edits Roche short-term memory, facts, core memory, mounts, or writeback. */
function normalizeRocheMemoryDedupText(value=''){
  return String(value??'')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[“”‘’'"`]/g,'')
    .replace(/[\s\u3000]+/g,'')
    .replace(/[，。！？、；：,.!?;:~～·•…—_\-()（）\[\]【】{}<>《》]/g,'');
}
function rocheMemoryDiceSimilarity(a,b){
  const left=normalizeRocheMemoryDedupText(a);
  const right=normalizeRocheMemoryDedupText(b);
  if(left===right)return left?1:0;
  if(left.length<20 || right.length<20)return 0;
  const grams=value=>{
    const map=new Map();
    for(let i=0;i<=value.length-3;i++){
      const gram=value.slice(i,i+3);
      map.set(gram,(map.get(gram)||0)+1);
    }
    return map;
  };
  const ga=grams(left),gb=grams(right);
  let overlap=0,totalA=0,totalB=0;
  ga.forEach(v=>{totalA+=v;});
  gb.forEach(v=>{totalB+=v;});
  ga.forEach((v,k)=>{if(gb.has(k))overlap+=Math.min(v,gb.get(k));});
  return (totalA+totalB)?(2*overlap)/(totalA+totalB):0;
}
function areRocheMemoryEntriesDuplicate(a,b){
  const at=normalizeRocheMemoryDedupText(a?.text||'');
  const bt=normalizeRocheMemoryDedupText(b?.text||'');
  if(!at || !bt)return {duplicate:false,reason:''};

  const bothShort=a?.kind==='short' && b?.kind==='short';
  if(bothShort){
    const aw=normalizeRocheMemoryDedupText(a?.who||'');
    const bw=normalizeRocheMemoryDedupText(b?.who||'');
    if(aw!==bw)return {duplicate:false,reason:''};
  }

  if(at===bt){
    if(bothShort || Math.min(at.length,bt.length)>=8)return {duplicate:true,reason:'exact'};
  }

  const minLen=Math.min(at.length,bt.length);
  const maxLen=Math.max(at.length,bt.length);
  if(minLen<20 || !maxLen)return {duplicate:false,reason:''};
  const ratio=minLen/maxLen;
  if(ratio>=0.84 && (at.includes(bt)||bt.includes(at)))return {duplicate:true,reason:'near'};
  if(rocheMemoryDiceSimilarity(at,bt)>=0.93)return {duplicate:true,reason:'near'};
  return {duplicate:false,reason:''};
}
function dedupeRocheMemoryEntries(entries=[]){
  const kept=[];
  let exactRemoved=0;
  let nearRemoved=0;
  const priority={core:3,fact:2,short:1};

  (Array.isArray(entries)?entries:[]).forEach(entry=>{
    let duplicateIndex=-1;
    let duplicateReason='';
    for(let i=0;i<kept.length;i++){
      const match=areRocheMemoryEntriesDuplicate(entry,kept[i]);
      if(match.duplicate){duplicateIndex=i;duplicateReason=match.reason;break;}
    }
    if(duplicateIndex<0){kept.push(entry);return;}

    if(duplicateReason==='near')nearRemoved++;else exactRemoved++;
    const old=kept[duplicateIndex];
    if((priority[entry?.kind]||0)>(priority[old?.kind]||0))kept[duplicateIndex]=entry;
  });

  kept.sort((a,b)=>(Number(a?.order)||0)-(Number(b?.order)||0));
  return {kept,removed:exactRemoved+nearRemoved,exactRemoved,nearRemoved};
}

async function loadActorRocheMemoryContext(actorId){
  const id=normalizeSocialActorId(actorId);
  const actor=getRelationshipActor(id);
  if(!actor || actor.kind!=='roche')return {actorId:id,text:'',sources:[],reason:'not_roche_actor',dedupe:{removed:0,exactRemoved:0,nearRemoved:0}};

  const enabled=getActorMemorySources(id).filter(source=>source.enabled);
  if(!enabled.length)return {actorId:id,text:'',sources:[],reason:'no_enabled_sources',dedupe:{removed:0,exactRemoved:0,nearRemoved:0}};

  const rawSections=[];
  const allEntries=[];
  const errors=[];
  let order=0;

  for(let sourceIndex=0;sourceIndex<enabled.length;sourceIndex++){
    const source=enabled[sourceIndex];
    const entries=[];
    const shortLimit=Math.max(0,Number(source.shortLimit)||0);
    const factLimit=Math.max(0,Number(source.factLimit)||0);
    let rawShortCount=0;
    let rawFactCount=0;

    const pushEntry=(kind,text,who='')=>{
      const raw=String(text||'').trim();
      if(!raw)return;
      const clean=_sanitize(raw);
      if(!clean||clean.length<5)return;
      const rendered=kind==='core'?`【核心记忆】${clean}`:kind==='fact'?`【事实】${clean}`:`${who||'对方'}：${clean}`;
      const entry={kind,text:clean,who:String(who||''),rendered,sourceIndex,conversationId:source.conversationId,order:order++};
      entries.push(entry);
      allEntries.push(entry);
    };

    if(shortLimit>0){
      try{
        const msgs=await bridgeGetShortTermMemory({conversationId:source.conversationId,limit:shortLimit});
        (msgs||[]).forEach(msg=>{
          const content=String(msg?.text||'');
          if(!content || shouldIgnoreRocheMemoryText(content))return;
          const who=msg.senderHandle||msg.senderName||(msg.isMe?'user':'对方');
          pushEntry('short',content,who);
          rawShortCount++;
        });
      }catch(error){
        errors.push({conversationId:source.conversationId,stage:'short',message:error?.message||String(error)});
      }
    }

    if(factLimit>0 || source.coreEnabled){
      try{
        const lt=await bridgeGetLongTermMemory({conversationId:source.conversationId,limit:factLimit||50});
        if(source.coreEnabled && lt?.core?.summary){
          pushEntry('core',lt.core.summary);
          rawFactCount++;
        }
        if(factLimit>0 && Array.isArray(lt?.facts)){
          lt.facts.slice(0,factLimit).forEach(fact=>{
            const content=fact?.summaryText||fact?.action||fact?.text||'';
            if(content){pushEntry('fact',content);rawFactCount++;}
          });
        }
      }catch(error){
        errors.push({conversationId:source.conversationId,stage:'long',message:error?.message||String(error)});
      }
    }

    rawSections.push({
      sourceIndex,
      conversationId:source.conversationId,
      conversationName:source.conversationName,
      isGroup:source.isGroup,
      rawShortCount,
      rawFactCount,
      entries
    });
  }

  const deduped=dedupeRocheMemoryEntries(allEntries);
  const keptSet=new Set(deduped.kept);
  const sections=[];
  rawSections.forEach(section=>{
    const kept=section.entries.filter(entry=>keptSet.has(entry));
    if(!kept.length)return;
    const shortCount=kept.filter(entry=>entry.kind==='short').length;
    const factCount=kept.length-shortCount;
    sections.push({
      conversationId:section.conversationId,
      conversationName:section.conversationName,
      isGroup:section.isGroup,
      shortCount,
      factCount,
      rawShortCount:section.rawShortCount,
      rawFactCount:section.rawFactCount,
      dedupedCount:Math.max(0,(section.rawShortCount+section.rawFactCount)-(shortCount+factCount)),
      text:`【${section.isGroup?'群聊':'单聊'} · ${section.conversationName||section.conversationId}】\n${kept.map(entry=>entry.rendered).join('\n')}`
    });
  });

  return {
    actorId:id,
    actorName:actor.name,
    sources:sections,
    errors,
    dedupe:{removed:deduped.removed,exactRemoved:deduped.exactRemoved,nearRemoved:deduped.nearRemoved,rawCount:allEntries.length,keptCount:deduped.kept.length},
    reason:sections.length?'':(errors.length?'read_failed':'mounted_sources_empty'),
    text:sections.map(section=>section.text).join('\n\n')
  };
}

function buildActorSyncSummary(actorId,{limit=30}={}){
  const id=normalizeSocialActorId(actorId);
  const actor=getRelationshipActor(id);
  if(!actor || actor.kind!=='roche')return null;

  const all=getActorUnsyncedKnowledge(id);
  if(!all.length)return null;

  const chosen=all.slice(0,Math.max(1,limit));
  const groups=new Map();
  let maxLearnedAt=0;

  chosen.forEach(({entry,event})=>{
    const line=perspectiveLineForEvent(event,id);
    if(!line)return;
    const section=memorySectionForType(event.type);
    if(!groups.has(section))groups.set(section,[]);
    groups.get(section).push(`- ${line}`);
    maxLearnedAt=Math.max(maxLearnedAt,Number(entry.learnedAt||0));
  });

  if(!groups.size)return null;

  const now=new Date().toLocaleString('zh-CN',{
    month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false
  });
  const bodyLines=[
    `角色：${actor.name}${actor.handle?`（@${actor.handle}）`:''}`,
    `user：${userProfileState.displayName||userProfileState.id}（@${userProfileState.id}）`,
    '',
    '以下只记录我实际做过、收到过或确实知道的 INS 社交，不包含我没有看到的公开内容：',
    ''
  ];

  ['Story','Feed','Reels','INS 私信','其他社交'].forEach(section=>{
    const rows=groups.get(section);
    if(!rows?.length)return;
    bodyLines.push(`【${section}】`);
    bodyLines.push(...rows);
    bodyLines.push('');
  });

  bodyLines.push('这是我的私人社交记忆。之后聊天时可以自然记得并延续，但不需要向 user 逐字复述这份记录。');

  const memoryBody=bodyLines.join('\n').trim();
  const summary=[
    INS_MEMORY_SYNC_PREFIX,
    `[TIME]${now}[/TIME]`,
    `[COUNT]${chosen.length}[/COUNT]`,
    '[MEMORY]',
    memoryBody,
    '[/MEMORY]',
    '[/RocheINSSync]'
  ].join('\n');

  const target=getActorWritebackTarget(id);
  return {
    actorId:id,
    actorName:actor.name,
    actorHandle:actor.handle||'',
    conversationId:target?.conversationId || '',
    conversationName:target?.conversationName || '',
    eventCount:chosen.length,
    maxLearnedAt,
    hasMore:all.length>chosen.length,
    summary
  };
}

function buildAllRocheSyncPayloads(limitPerActor=30,actorIds=null){
  const allow=actorIds ? new Set([].concat(actorIds).map(normalizeSocialActorId)) : null;
  return getRelationshipActors()
    .filter(actor=>actor.kind==='roche' && (!allow || allow.has(actor.id)))
    .map(actor=>buildActorSyncSummary(actor.id,{limit:limitPerActor}))
    .filter(Boolean);
}

function markActorSyncCommitted(actorId,maxLearnedAt){
  const id=normalizeSocialActorId(actorId);
  const ts=Number(maxLearnedAt||0);
  if(!id || !ts)return false;
  insSocialMemoryState.syncCursor[id]=Math.max(Number(insSocialMemoryState.syncCursor[id]||0),ts);
  persistINSSocialMemory();
  renderINSMemoryBridge();
  return true;
}

function setActorMemoryMount(actorId,conversationId,conversationName=''){
  const id=normalizeSocialActorId(actorId);
  if(!id)return;
  const target={
    conversationId:String(conversationId||''),
    conversationName:String(conversationName||conversationId||''),
    isGroup:false
  };
  insSocialMemoryState.mounts[id]=target;
  insSocialMemoryState.writebackTargets[id]=target;
  persistINSSocialMemory();
}

function shouldIgnoreRocheMemoryText(text){
  const value=String(text||'').trim();
  return value.startsWith(INS_MEMORY_SYNC_PREFIX) || value.startsWith(INS_MEMORY_SYNC_LEGACY_PREFIX);
}

async function syncPendingKnowledgeToRoche(actorIds=null){
  const bridge=window.NiniINSRocheBridge;
  const payloads=buildAllRocheSyncPayloads(30,actorIds);

  if(!bridge || typeof bridge.injectShortTerm!=='function'){
    return {ok:false,reason:'bridge_not_connected',payloads};
  }

  const results=[];
  for(const payload of payloads){
    if(!payload.conversationId){
      results.push({actorId:payload.actorId,ok:false,reason:'single_chat_not_found'});
      continue;
    }
    try{
      const result=await bridge.injectShortTerm(payload);
      if(result!==false){
        markActorSyncCommitted(payload.actorId,payload.maxLearnedAt);
        results.push({actorId:payload.actorId,ok:true});
      }else{
        results.push({actorId:payload.actorId,ok:false,reason:'write_rejected'});
      }
    }catch(error){
      results.push({actorId:payload.actorId,ok:false,reason:error?.message||'write_failed'});
    }
  }

  return {ok:payloads.length===0?true:results.every(row=>row.ok),results,payloads};
}

const insMemoryRealtimeActorQueue=new Set();

/* v5.0: no timed/idle writeback.
   During the session we only mark which Roche roles gained new INS knowledge.
   Automatic writeback happens when the INS app closes/unmounts. */
function queueINSMemoryRealtimeSync(actorId){
  const id=normalizeSocialActorId(actorId);
  const actor=typeof getRelationshipActor==='function' ? getRelationshipActor(id) : null;
  if(!actor || actor.kind!=='roche')return;
  insMemoryRealtimeActorQueue.add(id);
}

/* Kept as an explicit/manual hook for future realtime experiments.
   Nothing calls this automatically in v5.0. */
async function flushINSMemoryRealtimeQueue(){
  const ids=[...insMemoryRealtimeActorQueue];
  if(!ids.length)return {ok:true,results:[],payloads:[]};
  return await syncPendingKnowledgeToRoche(ids);
}

async function flushCurrentINSSessionOnClose(){
  const result=await syncPendingKnowledgeToRoche();
  insMemoryRealtimeActorQueue.clear();
  return result;
}

async function primeINSMemoryRocheConnections(){
  const roles=getRelationshipActors().filter(actor=>actor.kind==='roche');
  for(const actor of roles){
    await refreshActorMemoryConversations(actor.id);
  }
}

function currentStoryMemoryContentId(owner){
  try{
    const archive=ensureStoryArchive(owner);
    return archive?.at(-1)?.batchId || `story_batch:${owner}`;
  }catch(e){
    return `story_batch:${owner}`;
  }
}

function getEventDisplaySummary(event){
  if(event.summary)return compactMemoryText(event.summary,160);
  return perspectiveLineForEvent(event,'user');
}

function getEventCategoryLabel(event){
  const type=String(event?.type||'');
  const actorFormal=isFormalSocialActor(event?.actorId);
  const ownerFormal=isFormalSocialActor(event?.contentOwnerId);
  const related=(event?.relatedActorIds||[]).some(isFormalSocialActor);
  if(related && !actorFormal && !ownerFormal)return '公开提及';
  if(type.includes('publish'))return '角色发布';
  if(type.startsWith('dm_'))return 'DM';
  if(type.startsWith('story_'))return 'Story 互动';
  if(type.includes('comment'))return '评论互动';
  return '角色相关';
}

let activeINSMemorySourceActorId='';

function renderINSMemoryBridge(){
  const stats=document.getElementById('insMemoryStats');
  const roleList=document.getElementById('insMemoryRoleList');
  const eventList=document.getElementById('insMemoryEventList');
  if(!stats || !roleList || !eventList)return;

  const roles=getRelationshipActors().filter(actor=>actor.kind==='roche');
  const pendingPayloads=buildAllRocheSyncPayloads();
  const knownCount=Object.values(insSocialMemoryState.knowledge)
    .reduce((sum,ledger)=>sum+(ledger?.length||0),0);

  stats.innerHTML=`
    <div class="ins-memory-stat"><strong>${insSocialMemoryState.events.length}</strong><span>角色相关事件</span></div>
    <div class="ins-memory-stat"><strong>${knownCount}</strong><span>Knowledge 索引</span></div>
    <div class="ins-memory-stat"><strong>${pendingPayloads.length}</strong><span>待回传角色</span></div>
  `;

  roleList.innerHTML=roles.length ? roles.map(actor=>{
    const pending=getActorUnsyncedKnowledge(actor.id).length;
    const sources=getActorMemorySources(actor.id);
    const enabledSources=sources.filter(source=>source.enabled).length;
    const target=getActorWritebackTarget(actor.id);

    return `
      <div class="ins-memory-role">
        <div class="ins-memory-avatar" data-identity-avatar="${prEscape(actor.id)}">${prEscape(actor.initial)}</div>
        <div class="ins-memory-role-main">
          <strong>${prEscape(actor.name)}</strong>
          <span>${enabledSources?`读取 ${enabledSources}/${sources.length} 个会话`:(sources.length?'当前未启用记忆来源':'尚未读取 Roche 会话')} · ${target?`回传：${prEscape(target.conversationName||target.conversationId)}`:'尚未挂载单聊'} · 已知 ${getActorKnowledgeLedger(actor.id).length} 条</span>
        </div>
        <span class="ins-memory-badge ${pending?'pending':''}">${pending?`待同步 ${pending}`:'无新增'}</span>
        <div class="ins-memory-role-actions">
          <button class="ins-memory-source-btn" data-ins-memory-source="${prEscape(actor.id)}" type="button">挂载</button>
          <button class="ins-memory-preview-btn" data-ins-memory-preview="${prEscape(actor.id)}" type="button">预览</button>
        </div>
      </div>`;
  }).join('') : '<div class="pr-empty">当前还没有引入 Roche 角色。</div>';

  hydrateIdentityAvatars?.(roleList);

  const recent=insSocialMemoryState.events.slice(-12).reverse();
  eventList.innerHTML=recent.length ? recent.map(event=>{
    const known=getKnownActorIdsForEvent(event.eventId).map(socialActorName).join('、') || '无人';
    return `
      <div class="ins-memory-event">
        <div class="ins-memory-event-head">
          <strong>${prEscape(getEventCategoryLabel(event))} · ${prEscape(event.type)}</strong>
          <span>${prEscape(event.visibility)}</span>
        </div>
        <div class="ins-memory-event-copy">${prEscape(getEventDisplaySummary(event))}</div>
        <div class="ins-memory-event-known">已知：${prEscape(known)}</div>
      </div>`;
  }).join('') : '<div class="pr-empty">还没有新的角色相关事件。纯路人动态和路人闲聊不会进入这里。</div>';
}

function openINSMemoryBridge(){
  closeProfileDrawer?.();
  renderINSMemoryBridge();
  showRoute('routeMemoryBridge');
}

function closeINSMemorySheets(){
  activeINSMemorySourceActorId='';
  document.getElementById('insMemorySheetDim')?.classList.remove('show');
  document.getElementById('insMemoryPreviewSheet')?.classList.remove('show');
  document.getElementById('insMemorySourceSheet')?.classList.remove('show');
}
function closeINSMemoryPreview(){closeINSMemorySheets()}

function openINSMemoryPreview(actorId){
  const actor=getRelationshipActor(actorId);
  if(!actor)return;
  const payload=buildActorSyncSummary(actorId);
  document.getElementById('insMemoryPreviewTitle').textContent=`${actor.name} · Roche 回传预览`;

  if(!payload){
    document.getElementById('insMemoryPreviewMeta').textContent='当前没有需要同步的新 Knowledge；不会向 Roche 写空记录。';
    document.getElementById('insMemoryPreviewText').textContent='（无新增）';
  }else{
    document.getElementById('insMemoryPreviewMeta').textContent=
      `${payload.eventCount} 条 Knowledge · ${payload.hasMore?'还有下一批未包含 · ':''}${payload.conversationId?`自动回传到：${payload.conversationName||payload.conversationId}`:'尚未找到角色单聊'} · 预览不会推进同步游标`;
    document.getElementById('insMemoryPreviewText').textContent=payload.summary;
  }
  document.getElementById('insMemorySheetDim')?.classList.add('show');
  document.getElementById('insMemoryPreviewSheet')?.classList.add('show');
}

function renderINSMemorySourceSheet(actorId){
  const id=normalizeSocialActorId(actorId);
  const actor=getRelationshipActor(id);
  if(!actor)return;

  activeINSMemorySourceActorId=id;
  const sources=getActorMemorySources(id);
  const target=getActorWritebackTarget(id);

  document.getElementById('insMemorySourceTitle').textContent=`${actor.name} · 挂载的会话记忆`;
  const discoverySelect=document.getElementById('insMemoryDiscoverySelect');
  if(discoverySelect)discoverySelect.value=getActorPublicDiscoveryLevel(id);
  document.getElementById('insMemorySourceMeta').textContent=
    '只显示包含该 char 的 Roche 会话。打开开关才会读取；短期默认 50。开启的单聊同时作为“关闭 INS 时”的回传目标；群聊只读不写。';

  const list=document.getElementById('insMemorySourceList');
  list.innerHTML=sources.length ? sources.map(source=>{
    const isTarget=!!(target && target.conversationId===source.conversationId);
    const sub=source.enabled
      ? (source.isGroup?'群聊 · 已挂载读取':'单聊 · 已挂载读取'+(isTarget?' · 关闭时回传':'') )
      : (source.isGroup?'群聊':'单聊');
    return `
      <div class="ins-memory-source ${source.enabled?'on':''}" data-memory-source-id="${prEscape(source.conversationId)}">
        <div class="ins-memory-source-head">
          <div class="ins-memory-source-main">
            <strong>${prEscape(source.conversationName||source.conversationId)}</strong>
            <span>${prEscape(sub)}</span>
          </div>
          <button class="ins-memory-source-toggle ${source.enabled?'on':''}" data-memory-source-toggle="${prEscape(source.conversationId)}" type="button"><i></i></button>
        </div>
        ${source.enabled?`
          <div class="ins-memory-source-opts">
            <label>短期
              <input type="number" min="0" max="500" value="${Number(source.shortLimit)||0}" data-memory-source-short="${prEscape(source.conversationId)}">
            </label>
            <label>事实
              <input type="number" min="0" max="500" value="${Number(source.factLimit)||0}" data-memory-source-fact="${prEscape(source.conversationId)}">
            </label>
            <label class="ins-memory-core-toggle">
              <input type="checkbox" ${source.coreEnabled?'checked':''} data-memory-source-core="${prEscape(source.conversationId)}">
              核心
            </label>
          </div>
        `:''}
      </div>`;
  }).join('') : `
    <div class="ins-memory-empty-source">
      该 char 还没有读取到可挂载会话。请先在 Roche 与这个 char 建立单聊或群聊，然后点下面“刷新 Roche 会话”。
    </div>`;

  document.getElementById('insMemoryWritebackInfo').innerHTML=target
    ? `<strong>双向挂载已建立</strong>Roche → INS 会读取你开启的会话；INS → Roche 在关闭插件时只回传到单聊「${prEscape(target.conversationName||target.conversationId)}」。`
    : `<strong>当前仅可单向读取</strong>如果你只开启群聊，INS 可以读取群聊上下文，但不会写回。要启用关闭时回传，请打开该 char 的单聊开关。`;

  const refreshBtn=document.getElementById('insMemorySourceRefresh');
  if(refreshBtn && refreshBtn.dataset.loading!=='1'){
    refreshBtn.disabled=!window.NiniINSRocheBridge;
    refreshBtn.textContent='刷新 Roche 会话';
  }
  document.getElementById('insMemorySheetDim')?.classList.add('show');
  document.getElementById('insMemorySourceSheet')?.classList.add('show');
}

async function openINSMemorySourceSheet(actorId){
  const id=normalizeSocialActorId(actorId);
  renderINSMemorySourceSheet(id);

  const meta=document.getElementById('insMemorySourceMeta');
  if(meta)meta.textContent='正在读取包含该 char 的 Roche 会话…';

  const result=await refreshActorMemoryConversations(id);

  if(activeINSMemorySourceActorId===id){
    renderINSMemorySourceSheet(id);
    if(result.ok){
      const count=Array.isArray(result.conversations)?result.conversations.length:0;
      document.getElementById('insMemorySourceMeta').textContent=
        `已读取 ${count} 个包含该 char 的 Roche 会话。打开开关后才会作为记忆读取。`;
    }else{
      document.getElementById('insMemorySourceMeta').textContent=
        result.reason==='bridge_not_connected'
          ? '当前没有连接到 Roche 会话接口。'
          : `读取 Roche 会话失败：${result.reason}。你仍可使用上一次成功读取并保存的挂载。`;
    }
  }
}

function bindINSSocialMemoryUI(){
  document.getElementById('drawerMemorySystemBtn')?.addEventListener('click',openINSMemoryBridge);

  document.getElementById('insMemoryRoleList')?.addEventListener('click',event=>{
    const sourceBtn=event.target.closest('[data-ins-memory-source]');
    if(sourceBtn){
      void openINSMemorySourceSheet(sourceBtn.dataset.insMemorySource);
      return;
    }
    const previewBtn=event.target.closest('[data-ins-memory-preview]');
    if(previewBtn)openINSMemoryPreview(previewBtn.dataset.insMemoryPreview);
  });

  document.getElementById('insMemorySourceList')?.addEventListener('click',event=>{
    const btn=event.target.closest('[data-memory-source-toggle]');
    if(!btn || !activeINSMemorySourceActorId)return;
    const conversationId=btn.dataset.memorySourceToggle;
    const source=getActorMemorySources(activeINSMemorySourceActorId).find(row=>row.conversationId===conversationId);
    if(!source)return;
    updateActorMemorySource(activeINSMemorySourceActorId,conversationId,{enabled:!source.enabled});
    renderINSMemorySourceSheet(activeINSMemorySourceActorId);
    renderINSMemoryBridge();
  });

  document.getElementById('insMemoryDiscoverySelect')?.addEventListener('change',event=>{
    if(!activeINSMemorySourceActorId)return;
    setActorPublicDiscoveryLevel(activeINSMemorySourceActorId,event.target.value||'normal');
    renderINSMemoryBridge();
  });

  document.getElementById('insMemorySourceList')?.addEventListener('change',event=>{
    if(!activeINSMemorySourceActorId)return;
    const target=event.target;
    if(target.matches('[data-memory-source-short]')){
      updateActorMemorySource(activeINSMemorySourceActorId,target.dataset.memorySourceShort,{shortLimit:target.value});
    }else if(target.matches('[data-memory-source-fact]')){
      updateActorMemorySource(activeINSMemorySourceActorId,target.dataset.memorySourceFact,{factLimit:target.value});
    }else if(target.matches('[data-memory-source-core]')){
      updateActorMemorySource(activeINSMemorySourceActorId,target.dataset.memorySourceCore,{coreEnabled:target.checked});
    }
    renderINSMemoryBridge();
  });

  document.getElementById('insMemorySourceRefresh')?.addEventListener('click',async()=>{
    if(!activeINSMemorySourceActorId)return;
    const btn=document.getElementById('insMemorySourceRefresh');
    if(!btn || btn.dataset.loading==='1')return;

    btn.dataset.loading='1';
    btn.disabled=true;
    btn.textContent='读取中…';

    const id=activeINSMemorySourceActorId;
    try{
      const result=await refreshActorMemoryConversations(id);

      if(activeINSMemorySourceActorId===id){
        renderINSMemorySourceSheet(id);

        if(result.ok){
          const count=Array.isArray(result.conversations)?result.conversations.length:0;
          document.getElementById('insMemorySourceMeta').textContent=
            `已读取 ${count} 个包含该 char 的 Roche 会话。打开开关后才会作为记忆读取。`;
        }else{
          document.getElementById('insMemorySourceMeta').textContent=
            result.reason==='bridge_not_connected'
              ? '当前没有连接到 Roche 会话接口。'
              : `读取 Roche 会话失败：${result.reason}。已保留上一次成功读取的挂载列表。`;
        }
      }
    }finally{
      // v5.0.2: no matter success / error / timeout, never leave the UI stuck at “读取中…”
      btn.dataset.loading='0';
      btn.disabled=!window.NiniINSRocheBridge;
      btn.textContent='刷新 Roche 会话';
    }
  });

  document.getElementById('insMemoryPreviewClose')?.addEventListener('click',closeINSMemorySheets);
  document.getElementById('insMemorySourceClose')?.addEventListener('click',closeINSMemorySheets);
  document.getElementById('insMemorySheetDim')?.addEventListener('click',closeINSMemorySheets);
}

