const CHAR_GENERATION_PREF_STORAGE_KEY='nini_ins_char_generation_pref_v5019';
const CHAR_ACTIVE_PUBLISH_STORAGE_KEY='nini_ins_char_active_publish_v5019';
const CHAR_ACTIVE_MIN_MINUTES=30;
const CHAR_ACTIVE_JITTER=.20;
const CHAR_ACTIVE_CHECK_MS=60*1000;

function loadJSONLocalState(key){
  try{const raw=localStorage.getItem(key);const parsed=raw?JSON.parse(raw):{};return parsed&&typeof parsed==='object'?parsed:{};}catch(e){return {};}
}
function saveJSONLocalState(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch(e){console.warn('[INS] local save failed',key,e);return false;}}
const charGenerationPreferenceState=loadJSONLocalState(CHAR_GENERATION_PREF_STORAGE_KEY);
const charActivePublishState=loadJSONLocalState(CHAR_ACTIVE_PUBLISH_STORAGE_KEY);
const charAutoPublishBusy=new Set();

function charSettingKey(ref){return resolveCharProfileKey(ref||currentCharProfile||'')||normalizeSocialActorId(ref||currentCharProfile||'')||String(ref||currentCharProfile||'');}
function ensureCharGenerationPreference(ref){
  const key=charSettingKey(ref);if(!key)return {social:'',posting:'',visual:''};
  if(!charGenerationPreferenceState[key])charGenerationPreferenceState[key]={social:'',posting:'',visual:'',updatedAt:0};
  return charGenerationPreferenceState[key];
}
function getCharGenerationPreferencePrompt(ref,surface='feed'){
  const pref=ensureCharGenerationPreference(ref);
  const rows=[
    pref.social?`社交氛围：${pref.social}`:'',
    pref.posting?`发帖风格：${pref.posting}`:'',
    pref.visual?`图片/视频意图：${pref.visual}`:''
  ].filter(Boolean);
  if(!rows.length)return '';
  const actor=getRelationshipActor(normalizeSocialActorId(ref));
  return `【${actor?.name||ref} · 长期生成偏好（软倾向）】\n${rows.join('\n')}\n当前 surface：${surface}。这些偏好负责“通常怎么发/怎么拍”，不改写人设、记忆、关系、语言和地点事实；如果本次批次有临时主题，优先满足本次主题，再保留这些长期风格。`;
}
function buildCharGenerationPreferenceBatchPrompt(actorIds=[],surface='feed'){
  const blocks=[...new Set((actorIds||[]).map(normalizeSocialActorId).filter(Boolean))].map(id=>getCharGenerationPreferencePrompt(id,surface)).filter(Boolean);
  return blocks.join('\n\n');
}
function composeCharGenerationPrompt({actorIds=[],surface='feed',batchPrompt='',extraPrompt=''}){
  const persistent=buildCharGenerationPreferenceBatchPrompt(actorIds,surface);
  const albumPrompt=typeof buildCharAlbumGenerationPrompt==='function'?buildCharAlbumGenerationPrompt(actorIds,surface):'';
  const temporary=String(batchPrompt||'').trim();
  const tempBlock=temporary?`【本次批次临时偏好】\n${temporary}\n只影响这一次生成的主题/场景；不要把它写回角色长期设定。`:'';
  return [extraPrompt,tempBlock,persistent,albumPrompt].filter(Boolean).join('\n\n');
}

function ensureCharActivePublish(ref){
  const key=charSettingKey(ref);if(!key)return null;
  if(!charActivePublishState[key]){
    charActivePublishState[key]={
      feed:{enabled:false,intervalMin:180,nextAt:0},
      story:{enabled:false,intervalMin:180,nextAt:0},
      reels:{enabled:false,intervalMin:240,nextAt:0},
      updatedAt:0
    };
  }
  const state=charActivePublishState[key];
  ['feed','story','reels'].forEach(surface=>{
    if(!state[surface]||typeof state[surface]!=='object')state[surface]={enabled:false,intervalMin:surface==='reels'?240:180,nextAt:0};
    state[surface].enabled=!!state[surface].enabled;
    state[surface].intervalMin=Math.max(CHAR_ACTIVE_MIN_MINUTES,Number(state[surface].intervalMin)|| (surface==='reels'?240:180));
    state[surface].nextAt=Number(state[surface].nextAt)||0;
  });
  return state;
}
function randomCharActiveInterval(baseMin){
  const base=Math.max(CHAR_ACTIVE_MIN_MINUTES,Number(baseMin)||CHAR_ACTIVE_MIN_MINUTES)*60*1000;
  return Math.round(base + base*CHAR_ACTIVE_JITTER*(Math.random()*2-1));
}
function fmtNextActiveTime(ts){
  if(!ts)return '未排程';
  try{return new Date(ts).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}catch(e){return ''+ts;}
}
