function renderCharFrequencyNextHint(ref=currentCharProfile){
  const hint=document.getElementById('charFrequencyNextHint');if(!hint)return;
  const state=ensureCharActivePublish(ref);if(!state){hint.textContent='';return;}
  hint.textContent=['feed','story','reels'].map(surface=>{
    const row=state[surface];
    const label=surface==='feed'?'Feed':surface==='story'?'Story':'Reels';
    return `${label}：${row.enabled?fmtNextActiveTime(row.nextAt):'关闭'}`;
  }).join(' · ');
}
