function removeINSSocialMemoryEvents(eventIds=[]){
  const ids=new Set([].concat(eventIds||[]).map(String).filter(Boolean));
  if(!ids.size||typeof insSocialMemoryState==='undefined')return 0;
  const before=insSocialMemoryState.events.length;
  insSocialMemoryState.events=insSocialMemoryState.events.filter(event=>!ids.has(String(event.eventId||'')));
  Object.keys(insSocialMemoryState.knowledge||{}).forEach(actorId=>{insSocialMemoryState.knowledge[actorId]=(insSocialMemoryState.knowledge[actorId]||[]).filter(entry=>!ids.has(String(entry.eventId||'')));});
  if(insSocialMemoryState.events.length!==before)persistINSSocialMemory?.();
  return before-insSocialMemoryState.events.length;
}
function findINSDMMemoryEventForRow(recipient,row){
  if(!row||typeof insSocialMemoryState==='undefined')return null;
  if(row._memoryEventId){const direct=insSocialMemoryState.events.find(event=>String(event.eventId)===String(row._memoryEventId));if(direct)return direct;}
  const recipientId=normalizeSocialActorId(recipient);
  return insSocialMemoryState.events.find(event=>event.type==='dm_message'&&event.contentId===`dm:${recipientId}`&&String(event.text||'')===String(row.text||'')&&Math.abs((Number(event.createdAt)||0)-(Number(row.createdAt)||0))<5)||null;
}
function removeINSDMMemoryForConversation(recipient){
  if(!recipient||typeof insSocialMemoryState==='undefined')return 0;
  const recipientId=normalizeSocialActorId(recipient);
  const ids=insSocialMemoryState.events.filter(event=>{if(event.visibility!=='private'||!String(event.type||'').startsWith('dm_'))return false;if(event.contentId===`dm:${recipientId}`)return true;const actor=normalizeSocialActorId(event.actorId);const targets=(event.targetIds||[]).map(normalizeSocialActorId);return(actor==='user'&&targets.includes(recipientId))||(actor===recipientId&&targets.includes('user'));}).map(event=>event.eventId);
  (dmBaseMessages[recipient]||[]).forEach(row=>{const event=findINSDMMemoryEventForRow(recipient,row);if(event?.eventId)ids.push(event.eventId);});
  return removeINSSocialMemoryEvents(ids);
}
function deleteDMMessageById(recipient,messageId){
  const rows=dmBaseMessages[recipient];if(!Array.isArray(rows))return false;
  const index=rows.findIndex(row=>String(row._uiId||'')===String(messageId||''));if(index<0)return false;
  const event=findINSDMMemoryEventForRow(recipient,rows[index]);if(event?.eventId)removeINSSocialMemoryEvents([event.eventId]);
  rows.splice(index,1);scheduleINSDMHistoryPersistence?.();updateDMListPreview?.(recipient);if(currentDMChat===recipient)renderDMChatStream(recipient);return true;
}
function deleteDMMessageAt(recipient,index){const row=(dmBaseMessages[recipient]||[])[Number(index)];return row?deleteDMMessageById(recipient,row._uiId):false;}
let dmBubbleDeleteTimer=null,dmBubbleDeleteState=null;

function clearDMBubbleDeleteTimer(){
  if(dmBubbleDeleteTimer){clearTimeout(dmBubbleDeleteTimer);dmBubbleDeleteTimer=null;}
  dmBubbleDeleteState=null;
}

function canRerollDMReplyMessage(recipient,messageId){
  const rows=dmBaseMessages[recipient]||[];
  const index=rows.findIndex(row=>String(row._uiId||'')===String(messageId||''));
  if(index<0)return false;
  const row=rows[index];
  const roundId=String(row?._replyRoundId||'');
  if(row?.from!=='them'||!roundId)return false;
  const firstIndex=rows.findIndex(item=>String(item?._replyRoundId||'')===roundId);
  if(firstIndex!==index)return false;
  // 重回只对当前最后一轮开放，避免改写旧回复后让后续对话变得前后矛盾。
  return rows.slice(index).every(item=>String(item?._replyRoundId||'')===roundId);
}

async function rerollDMReplyMessage(recipient,messageId){
  if(!recipient||dmAIReplyInFlight)return false;
  const rows=dmBaseMessages[recipient]||[];
  const first=rows.find(row=>String(row._uiId||'')===String(messageId||''));
  const roundId=String(first?._replyRoundId||'');
  if(!roundId||!canRerollDMReplyMessage(recipient,messageId))return false;

  const removedRows=rows.filter(row=>String(row?._replyRoundId||'')===roundId);
  const eventIds=removedRows.map(row=>findINSDMMemoryEventForRow(recipient,row)?.eventId).filter(Boolean);
  if(eventIds.length)removeINSSocialMemoryEvents(eventIds);

  dmBaseMessages[recipient]=rows.filter(row=>String(row?._replyRoundId||'')!==roundId);
  if(Array.isArray(dmSharedCards[recipient])){
    dmSharedCards[recipient]=dmSharedCards[recipient].filter(card=>String(card?._replyRoundId||'')!==roundId);
  }
  scheduleINSDMHistoryPersistence?.();
  updateDMListPreview?.(recipient);
  if(currentDMChat===recipient)renderDMChatStream(recipient);

  await dmSummonAI({reroll:true});
  return true;
}

function closeDMMessageActionMenu(){
  document.getElementById('dmMessageActionOverlayV122')?.remove();
}

function openDMMessageActionMenu(messageId){
  if(!currentDMChat||!messageId)return;
  const rows=dmBaseMessages[currentDMChat]||[];
  const row=rows.find(item=>String(item._uiId||'')===String(messageId||''));
  if(!row)return;

  closeDMMessageActionMenu();
  const host=document.querySelector('.phone')||document.body;
  const overlay=document.createElement('div');
  overlay.id='dmMessageActionOverlayV122';
  overlay.style.cssText='position:absolute;inset:0;z-index:10020;background:rgba(0,0,0,.12);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
  const panel=document.createElement('div');
  panel.style.cssText='width:min(286px,100%);padding:8px;background:rgba(248,248,250,.94);border:1px solid rgba(0,0,0,.08);border-radius:20px;box-shadow:0 16px 44px rgba(0,0,0,.20);backdrop-filter:blur(22px);-webkit-backdrop-filter:blur(22px);';
  const title=document.createElement('div');
  title.textContent='消息操作';
  title.style.cssText='padding:8px 10px 10px;text-align:center;font-size:12px;color:#8b8f96;font-weight:700;';
  panel.appendChild(title);

  const makeBtn=(label,danger=false)=>{
    const btn=document.createElement('button');
    btn.type='button';
    btn.textContent=label;
    btn.style.cssText=`width:100%;height:44px;border:0;border-radius:14px;background:${danger?'rgba(255,59,48,.08)':'rgba(255,255,255,.82)'};color:${danger?'#d92d20':'#111'};font-size:15px;font-weight:800;cursor:pointer;margin-top:6px;`;
    return btn;
  };

  if(canRerollDMReplyMessage(currentDMChat,messageId)){
    const reroll=makeBtn('重回');
    reroll.addEventListener('click',async ()=>{
      const recipient=currentDMChat;
      closeDMMessageActionMenu();
      await rerollDMReplyMessage(recipient,messageId);
    });
    panel.appendChild(reroll);
  }

  const del=makeBtn('删除',true);
  del.addEventListener('click',()=>{
    const recipient=currentDMChat;
    closeDMMessageActionMenu();
    deleteDMMessageById(recipient,messageId);
  });
  panel.appendChild(del);

  overlay.appendChild(panel);
  overlay.addEventListener('click',event=>{if(event.target===overlay)closeDMMessageActionMenu();});
  host.appendChild(overlay);
}

function armDMBubbleDelete(messageId,event){
  clearDMBubbleDeleteTimer();
  dmBubbleDeleteState={id:String(messageId||''),x:Number(event?.clientX)||0,y:Number(event?.clientY)||0,pointerId:event?.pointerId};
  dmBubbleDeleteTimer=setTimeout(()=>{
    const state=dmBubbleDeleteState;
    clearDMBubbleDeleteTimer();
    if(state?.id&&currentDMChat)openDMMessageActionMenu(state.id);
  },560);
}

const dmChatMessagesEl=document.getElementById('dmChatMessages');
dmChatMessagesEl?.addEventListener('pointerdown',event=>{
  const row=event.target.closest?.('[data-dm-msg-id]');
  if(!row||event.button>0)return;
  armDMBubbleDelete(row.dataset.dmMsgId,event);
},{passive:true});
dmChatMessagesEl?.addEventListener('pointermove',event=>{
  const state=dmBubbleDeleteState;
  if(!state)return;
  if(state.pointerId!==undefined&&state.pointerId!==event.pointerId)return;
  if(Math.hypot((Number(event.clientX)||0)-state.x,(Number(event.clientY)||0)-state.y)>10)clearDMBubbleDeleteTimer();
},{passive:true});
['pointerup','pointercancel','pointerleave'].forEach(type=>dmChatMessagesEl?.addEventListener(type,clearDMBubbleDeleteTimer,{passive:true}));
dmChatMessagesEl?.addEventListener('contextmenu',event=>{
  const row=event.target.closest?.('[data-dm-msg-id]');
  if(!row)return;
  event.preventDefault();
  clearDMBubbleDeleteTimer();
  openDMMessageActionMenu(row.dataset.dmMsgId);
});

function deleteFixedNPCFromDMHub(actorId){
  const id=String(actorId||''),actor=typeof getRelationshipActor==='function'?getRelationshipActor(id):null;if(!id||actor?.kind!=='npc')return;if(!confirm(`删除固定联系人 ${actor.name||id}？`))return;
  removeINSDMMemoryForConversation(id);delete dmBaseMessages[id];delete dmSharedCards[id];delete dmProfiles[id];
  if(typeof charProfileState!=='undefined'){delete charProfileState.profiles?.[id];delete charProfileState.boardBatches?.[id];delete charProfileState.boardIndex?.[id];}
  if(typeof relationshipGraphState!=='undefined')relationshipGraphState.edges=(relationshipGraphState.edges||[]).filter(edge=>edge.from!==id&&edge.to!==id);
  persistINSProfileState?.();
  persistCharGuestbookState?.();
  document.querySelectorAll(`#dmV2List [data-dm-chat="${CSS.escape(id)}"]`).forEach(row=>row.remove());scheduleINSDMHistoryPersistence?.();renderDMUserNpcHub?.();renderPeopleRelations?.();renderFeedShareDMRecipients?.();renderReelsV15DMRecipients?.();
}


