const feedGlassDim = document.getElementById('feedGlassDim');
const feedRefreshGlass = document.getElementById('feedRefreshGlass');
const feedNoticeGlass = document.getElementById('feedNoticeGlass');
const feedNoticeDot = document.getElementById('feedNoticeDot');
const INS_NOTIFICATION_STORAGE_KEY='nini-ins-unread-notifications-v1';
function loadINSNotificationState(){
  try{
    const parsed=JSON.parse(localStorage.getItem(INS_NOTIFICATION_STORAGE_KEY)||'[]');
    return Array.isArray(parsed)?parsed.filter(row=>row&&row.read!==true):[];
  }catch(e){return [];}
}
const insNotificationState=loadINSNotificationState();
function persistINSNotificationState(){
  try{localStorage.setItem(INS_NOTIFICATION_STORAGE_KEY,JSON.stringify(insNotificationState.filter(row=>row&&row.read!==true)));}catch(e){}
}
function formatINSNoticeTime(ts){
  const d=Math.max(0,Date.now()-Number(ts||Date.now()));
  if(d<60000)return '刚刚';
  if(d<3600000)return `${Math.max(1,Math.floor(d/60000))} 分钟前`;
  if(d<86400000)return `${Math.max(1,Math.floor(d/3600000))} 小时前`;
  return `${Math.max(1,Math.floor(d/86400000))} 天前`;
}
function pushINSNotification({actorId='',type='activity',copy='',emoji='',targetPostId=''}={}){
  const id=normalizeSocialActorId(actorId);
  if(!id||id==='user'||!isFormalSocialActor(id))return;
  insNotificationState.unshift({id:`n_${Date.now()}_${Math.random().toString(36).slice(2,5)}`,actorId:id,type,copy,emoji,targetPostId,createdAt:Date.now(),read:false});
  if(insNotificationState.length>50)insNotificationState.length=50;
  persistINSNotificationState();
  renderINSNotifications();
}
function renderINSNotifications(){
  const rows=insNotificationState.slice(0,30);
  const make=()=>rows.length?rows.map(row=>{
    const identity=getIdentityMeta(row.actorId);
    const attr=row.type==='dm'?`data-notice-dm="${escapeDMCardHTML(row.actorId)}"`:row.targetPostId?`data-notice-post="${escapeDMCardHTML(row.targetPostId)}"`:'';
    return `<button class="feed-notice-row clickable" ${attr} type="button"><div class="feed-notice-avatar" data-identity-avatar="${escapeDMCardHTML(row.actorId)}">${identity.avatarUrl?'':escapeDMCardHTML(identity.initial)}</div><div class="feed-notice-copy"><strong>${escapeDMCardHTML(identity.name)}</strong> ${escapeDMCardHTML(row.copy||'有新的互动')}<div class="feed-notice-time">${escapeDMCardHTML(formatINSNoticeTime(row.createdAt))}</div></div><div class="feed-notice-side">${row.emoji?escapeDMCardHTML(row.emoji):'<span class="feed-notice-chevron">›</span>'}</div></button>`;
  }).join(''):'<div class="route-empty">暂无新提醒</div>';
  const list=document.getElementById('feedNoticeList'); if(list){list.innerHTML=make();hydrateIdentityAvatars(list);}
  const route=document.getElementById('routeNotificationList'); if(route){route.innerHTML=make();hydrateIdentityAvatars(route);}
  if(feedNoticeDot)feedNoticeDot.style.display=rows.some(x=>!x.read)?'':'none';
}
function markINSNotificationsRead(){
  /* Current visible DOM remains readable for this opening; only future openings are cleared. */
  insNotificationState.length=0;
  persistINSNotificationState();
  if(feedNoticeDot)feedNoticeDot.style.display='none';
}
function handleINSNotificationClick(e){
  const dm=e.target.closest('[data-notice-dm]'); if(dm){closeFeedGlass();openDMChat(dm.dataset.noticeDm);return;}
  const post=e.target.closest('[data-notice-post]'); if(post){closeFeedGlass();state.active='home';renderNav();openCommentsForPost(post.dataset.noticePost);}
}
