document.getElementById('storyCreateItems')?.addEventListener('input',e=>{
  const area=e.target.closest('[data-story-create-desc]');
  if(area){
    const index=Number(area.dataset.storyCreateDesc||0);
    if(storyCreateDraft.items[index]) storyCreateDraft.items[index].description=area.value;
    return;
  }

  const urlInput=e.target.closest('[data-story-create-url]');
  if(urlInput){
    const index=Number(urlInput.dataset.storyCreateUrl||0);
    const item=storyCreateDraft.items[index];
    if(item && item.type==='image'){
      item.mediaUrl=urlInput.value.trim();
      item.mediaSource=item.mediaUrl?'url':'';
      item.generatedRequested=false;
      item.fileName='';
    }
  }
});

document.getElementById('storyCreateItems')?.addEventListener('change',async e=>{
  const fileInput=e.target.closest('[data-story-create-file]');
  if(fileInput){
    const index=Number(fileInput.dataset.storyCreateFile||0);
    const item=storyCreateDraft.items[index];
    const file=fileInput.files?.[0];
    if(!item || item.type!=='image' || !file)return;

    try{
      item.mediaUrl=await readAlbumFileAsDataUrl(file);
      item.mediaSource='upload';
      item.fileName=file.name;
      item.generatedRequested=false;
      renderStoryCreateDraft();
    }catch(error){
      console.warn('[INS] 读取本地 Story 图片失败',error);
      alert('本地图片读取失败，请重新选择');
    }
    return;
  }

  const urlInput=e.target.closest('[data-story-create-url]');
  if(urlInput){
    const index=Number(urlInput.dataset.storyCreateUrl||0);
    const item=storyCreateDraft.items[index];
    if(!item || item.type!=='image')return;

    item.mediaUrl=urlInput.value.trim();
    item.mediaSource=item.mediaUrl?'url':'';
    item.generatedRequested=false;
    item.fileName='';
    renderStoryCreateDraft();
  }
});
document.getElementById('storyCreateItems')?.addEventListener('click',async e=>{
  const removeBtn=e.target.closest('[data-story-create-remove]');
  if(removeBtn){
    const index=Number(removeBtn.dataset.storyCreateRemove||0);
    storyCreateDraft.items.splice(index,1);
    renderStoryCreateDraft();
    return;
  }

  const generateBtn=e.target.closest('[data-story-create-generate]');
  if(generateBtn){
    const index=Number(generateBtn.dataset.storyCreateGenerate||0);
    const item=storyCreateDraft.items[index];
    if(!item || item.type!=='image')return;

    const desc=storyCreateDraft.items[index]?.description?.trim() || '';
    if(!desc){
      alert('先填写这张图片的描述，再生图');
      return;
    }

    try{
      const generated=await withINSImageButtonBusy(generateBtn,'生图中…',()=>requestRocheGeneratedImage({description:desc,entry:'story'}));
      item.generatedRequested=true;
      item.generated=true;
      item.mediaSource='generated';
      item.mediaUrl=generated.url;
      item.fileName='';
      renderStoryCreateDraft();
    }catch(error){
      const reason=String(error?.message||error||'未知错误');
      alert(reason==='bridge_not_connected'?'当前没有连接到 Roche 生图接口。请先在 Roche 生图设置里完成配置。':`生图失败：${reason}`);
    }
  }
});
