/* ===== INS-v5.0 Feed generation: Roche WebView-safe capture delegation ===== */
function getSelectedFeedChars(){
  return [...document.querySelectorAll('.feed-char-chip.on')].map(el=>el.dataset.feedChar).filter(Boolean);
}
function setINSGenerationButtonBusy(btn,busy,busyText='',idleText=''){
  if(!btn)return;
  if(busy){
    btn.dataset.idleText=btn.textContent;
    btn.disabled=true;
    btn.classList.add('busy');
    btn.classList.remove('selected');
    if(busyText)btn.textContent=busyText;
  }else{
    btn.disabled=false;
    btn.classList.remove('busy');
    btn.textContent=idleText||btn.dataset.idleText||btn.textContent;
  }
}
function resolveGeneratedActorId(row,selected,index=0){
  const raw=String(row?.actorId||row?.authorId||row?.author||'').replace(/^@/,'');
  if(raw){
    const hit=(selected||[]).find(id=>{const meta=getIdentityMeta(id);return id===raw||meta.handle===raw||meta.name===raw;});
    if(hit)return hit;
  }
  return (selected||[])[index%(selected||[]).length]||'';
}
function registerGeneratedPublicIdentity(row,index=0){
  const actor=row?.actor||{};
  const handle=String(actor.handle||row?.author||row?.handle||`public_${Date.now()}_${index}`).replace(/^@/,'');
  const name=String(actor.displayName||actor.name||row?.displayName||handle);
  publicIdentityRegistry[handle]={handle,name,initial:String(actor.initial||name||'?').slice(0,1).toUpperCase(),avatarUrl:STRANGER_AVATAR_URL,language:String(actor.language||row?.sourceLanguage||''),region:String(actor.region||''),location:String(actor.location||row?.location||''),bio:String(actor.bio||'')};
  return handle;
}
function getGeneratedItems(data){
  if(Array.isArray(data))return data;
  if(Array.isArray(data?.items))return data.items;
  if(Array.isArray(data?.posts))return data.posts;
  if(Array.isArray(data?.results))return data.results;
  if(data?.item)return [data.item];
  if(data?.post)return [data.post];
  return [];
}

/* v1.07.9 Home Feed generation reader.
   The main Feed generation call returns a Simplified-Chinese caption plus the
   intended source language. Original-language text is created later, only on
   demand, through the separately configured Feed translation API. */
function normalizeHomeFeedGeneratedCaption(row={}){
  const captionObject=row?.caption && typeof row.caption==='object'?row.caption:{};
  const translationObject=row?.translation && typeof row.translation==='object'?row.translation:{};
  const captionValue=typeof row?.caption==='string'?row.caption:'';
  const translationValue=typeof row?.translation==='string'?row.translation:'';
  const firstText=(...values)=>{
    for(const value of values){
      if((typeof value==='string'||typeof value==='number') && String(value).trim())return String(value).trim();
    }
    return '';
  };
  const chinese=firstText(
      row?.captionZh,row?.caption_zh,row?.translationZh,row?.translation_zh,
      row?.chineseTranslation,row?.textTranslation,row?.text_translation,translationValue,
      captionObject?.translation,captionObject?.zh,translationObject?.zh,
      translationObject?.chinese,translationObject?.text,
      row?.captionOriginal,row?.caption_original,row?.originalCaption,row?.original_caption,
      row?.textOriginal,row?.text_original,captionValue,row?.text,
      captionObject?.original,captionObject?.text,captionObject?.source
    );
  return {
    rawCaptionOriginal:chinese,
    captionOriginal:stripGeneratedCaptionHashtags(chinese).trim(),
    captionTranslation:'',
    sourceLanguage:firstText(row?.sourceLanguage,row?.source_language,row?.language,row?.actor?.language,row?.actor?.sourceLanguage)
  };
}

function generatedFeedRowNeedsTranslation(){return false;}

async function callNiniINSFeedSinglePass(task,payload={}){
  return callNiniINSAI(task,payload);
}

function makeGeneratedReelItem(row,actorId,kind='char',index=0){
  const bilingual=normalizeINSBilingualText({
    textOriginal:row?.captionOriginal??row?.caption??row?.textOriginal??row?.text??'',
    textTranslation:row?.captionTranslation??row?.translation??row?.textTranslation??'',
    sourceLanguage:row?.sourceLanguage
  });
  const metrics=row?.metrics||{};
  const initialComments=Array.isArray(row?.initialComments)?row.initialComments:[];
  const tags=normalizeGeneratedEnglishTags(row?.tags||[]);
  const videoDescription=String(
    row?.videoDescription??
    row?.mediaDescription??
    row?.content?.videoDescription??
    row?.content?.mediaDescription??
    row?.content??
    '随手短视频'
  ).trim()||'随手短视频';

  const identitySnapshot=kind==='stranger'?cloneINSDMJSON(getIdentityMeta(actorId),{}):null;
  return {
    id:`reel_ai_${Date.now()}_${index}_${Math.random().toString(36).slice(2,6)}`,
    author:actorId,
    initial:getIdentityMeta(actorId).initial||String(actorId||'?').slice(0,1).toUpperCase(),
    kind,
    identitySnapshot,
    followed:kind!=='stranger',
    liked:false,
    reposted:false,
    translated:false,
    likes:Math.max(0,Number(metrics.likes??row?.likes??0)||0),
    comments:Math.max(initialComments.length,Number(metrics.comments??row?.comments??0)||0),
    reposts:Math.max(0,Number(metrics.reposts??row?.reposts??0)||0),
    shares:Math.max(0,Number(metrics.shares??row?.shares??row?.dmShares??0)||0),
    videoDescription,
    caption:bilingual.textOriginal||'',
    captionTranslation:bilingual.textTranslation||'',
    sourceLanguage:bilingual.sourceLanguage||'',
    location:normalizeAIGeneratedCityLocationLabel(row?.location||row?.actor?.location||'',bilingual.sourceLanguage,bilingual.textOriginal,row?.actor?.region||row?.region||''),
    tags,
    generated:true,
    createdAt:Date.now()
  };
}

function recordGeneratedReelPublish(actorId,item,{knownByUser=true}={}){
  if(!actorId||!item||typeof recordSocialEvent!=='function')return;
  const caption=compactMemoryText(item.caption||'',160);
  const video=compactMemoryText(item.videoDescription||'',180);
  const mentionMeta=detectFormalActorMentions(`${item.caption||''} ${item.videoDescription||''}`);
  if(!isFormalSocialActor(actorId) && !mentionMeta.length)return;
  const actorName=socialActorName(actorId);
  const summary=[
    `${actorName}发布了一条 Reel。`,
    caption?`文案：“${caption}”`:'',
    video?`视频：${video}`:''
  ].filter(Boolean).join(' ');

  const known=[];
  if(isFormalSocialActor(actorId))known.push(actorId);
  if(knownByUser && isFormalSocialActor(actorId))known.push('user');

  recordSocialEvent({
    type:'reel_publish',
    actorId,
    targetIds:[],
    contentId:item.id,
    contentType:'reel',
    contentOwnerId:actorId,
    relatedActorIds:mentionMeta.map(row=>row.actorId),
    text:item.caption||'',
    visibility:'public',
    payload:{
      mentionMeta,
      videoDescription:item.videoDescription||'',
      caption:item.caption||'',
      captionTranslation:item.captionTranslation||'',
      tags:Array.isArray(item.tags)?item.tags:[],
      location:item.location||'',
      metrics:{
        likes:Number(item.likes)||0,
        comments:Number(item.comments)||0,
        reposts:Number(item.reposts)||0,
        shares:Number(item.shares)||0
      },
      generated:true
    },
    summary
  },{knownActorIds:known,learnedVia:'current_reels'});
}

function normalizeGeneratedMetric(value,min,max){
  const n=Number(value);
  if(Number.isFinite(n) && n>0)return Math.max(Number(min)||0,Math.round(n));
  return min + Math.floor(Math.random()*(Math.max(min,max)-min+1));
}

function stripGeneratedCaptionHashtags(text=''){
  return String(text||'').replace(/(^|\s)#[^\s#]+/g,'$1').replace(/\s{2,}/g,' ').trim();
}
function normalizeGeneratedEnglishTags(rawTags=[]){
  const rows=Array.isArray(rawTags)?rawTags:[];
  return [...new Set(rows.map(tag=>String(tag||'').trim()).filter(Boolean).map(tag=>tag.startsWith('#')?tag:'#'+tag).filter(tag=>/^#[A-Za-z0-9_.-]+$/.test(tag)))];
}
function inferGeneratedEnglishLocation(sourceLanguage='',text='',region=''){
  const lang=String(sourceLanguage||'').toLowerCase();
  const sample=(String(text||'')+' '+String(region||'')).toLowerCase();
  if(/hong\s*kong|香港/.test(sample))return 'Hong Kong·China';
  if(/macau|macao|澳门|澳門/.test(sample))return 'Macau·China';
  if(/taiwan|台湾|台灣|traditional/.test(sample))return 'Taiwan·China';
  if(/korean|ko\b|kr|한국|韩/.test(lang) || /[가-힣]/.test(text))return 'Seoul·Korea';
  if(/japanese|ja\b|jp|日本|日语/.test(lang) || /[ぁ-んァ-ヶー]/.test(text))return 'Tokyo·Japan';
  if(/thai|th\b|泰/.test(lang))return 'Bangkok·Thailand';
  if(/vietnamese|vi\b|越/.test(lang))return 'Ho Chi Minh City·Vietnam';
  if(/indonesian|id\b|印尼/.test(lang))return 'Jakarta·Indonesia';
  if(/french|fr\b|法/.test(lang))return 'Paris·France';
  if(/german|de\b|德/.test(lang))return 'Berlin·Germany';
  if(/spanish|es\b|西/.test(lang))return 'Madrid·Spain';
  if(/portuguese|pt\b|葡/.test(lang))return 'Lisbon·Portugal';
  if(/australia|australian/.test(sample))return 'Sydney·Australia';
  if(/united kingdom|\buk\b|britain|british/.test(sample))return 'London·UK';
  if(/canada|canadian/.test(sample))return 'Toronto·Canada';
  if(/english|en\b|英/.test(lang))return 'New York·USA';
  if(/chinese|zh\b|中文|汉语|漢語/.test(lang) || /[\u4e00-\u9fff]/.test(text))return 'Shanghai·China';
  return '';
}
function normalizeGeneratedLocationLabel(value='',sourceLanguage='',text='',region=''){
  const regionText=String(region||'');
  if(/hong\s*kong|香港/i.test(regionText))return 'Hong Kong·China';
  if(/macau|macao|澳门|澳門/i.test(regionText))return 'Macau·China';
  if(/taiwan|台湾|台灣/i.test(regionText))return 'Taiwan·China';
  let raw=String(value||'').trim();
  if(raw){
    raw=raw.replace(/\s*[•|]\s*/g,'·').replace(/,\s*/g,'·').replace(/\s*·\s*/g,'·');
    raw=raw.replace(/·(?:South\s+Korea|Republic\s+of\s+Korea)$/i,'·Korea');
    if(/·Taiwan$/i.test(raw))return 'Taiwan·China';
    if(/^(?:Hong\s+Kong)(?:·.*)?$/i.test(raw))return 'Hong Kong·China';
    if(/^(?:Macau|Macao)(?:·.*)?$/i.test(raw))return 'Macau·China';
    if(/[\u3400-\u9fff\u3040-\u30ff\uac00-\ud7af\u0e00-\u0e7f]/.test(raw))raw='';
  }
  return raw || inferGeneratedEnglishLocation(sourceLanguage,text,region);
}

function normalizeAIGeneratedCityLocationLabel(value='',sourceLanguage='',text='',region=''){
  const raw=normalizeGeneratedLocationLabel(value,sourceLanguage,text,region);
  if(!raw)return raw;
  const parts=String(raw).split('·').map(x=>x.trim()).filter(Boolean);
  if(parts.length<2)return raw;
  const place=parts[0];
  const country=parts.slice(1).join('·');
  const p=place.toLowerCase();

  // Generated content should display only city-level locations. Manual profile/post editing
  // still uses normalizeGeneratedLocationLabel directly and may remain more specific.
  if(/korea/i.test(country)){
    if(/seongsu|hongdae|gangnam|itaewon|hannam|yeonnam|apgujeong|cheongdam|myeongdong|samcheong|bukchon|jamsil|sinchon|euljiro|dongdaemun|insadong/.test(p))return 'Seoul·Korea';
    if(/haeundae|gwangalli|seomyeon|nampo/.test(p))return 'Busan·Korea';
    if(/(?:-dong|-gu|-ro|-gil|district|neighborhood|station)$/i.test(place)){
      return inferGeneratedEnglishLocation(sourceLanguage,text,region)||'Seoul·Korea';
    }
  }
  if(/japan/i.test(country)){
    if(/shibuya|harajuku|shinjuku|ginza|akihabara|asakusa|daikanyama|omotesando|shimokitazawa|nakameguro/.test(p))return 'Tokyo·Japan';
    if(/d[oō]tonbori|namba|shinsaibashi/.test(p))return 'Osaka·Japan';
  }
  if(/usa|united states/i.test(country) && /manhattan|brooklyn|queens|soho|chelsea|williamsburg/.test(p))return 'New York·USA';
  if(/france/i.test(country) && /montmartre|le marais|saint-germain/.test(p))return 'Paris·France';
  if(/uk|united kingdom/i.test(country) && /shoreditch|camden|notting hill|soho/.test(p))return 'London·UK';

  if(/(?:district|ward|neighborhood|quarter|street|road|avenue|station|mall|cafe|restaurant|hotel|museum)$/i.test(place)){
    return inferGeneratedEnglishLocation(sourceLanguage,text,region)||raw;
  }
  return raw;
}
function splitGeneratedCaptionText(text=''){
  const clean=String(text||'').replace(/\s+/g,' ').trim();
  if(!clean)return {short:'',long:''};
  const previewLimit=32;
  if(clean.length<=previewLimit)return {short:clean,long:''};
  const marks=['。','！','？','…','~','.','!','?','，',',',' '];
  let cut=-1;
  for(const mark of marks){
    const pos=clean.lastIndexOf(mark,previewLimit);
    if(pos>cut)cut=pos;
  }
  if(cut<14)cut=previewLimit-1;
  const short=clean.slice(0,cut+1).trim();
  const long=clean.slice(cut+1).trim();
  return {short:short||clean,long};
}
function normalizeGeneratedMediaItems(row={}){
  const raw=Array.isArray(row?.mediaItems)
    ? row.mediaItems
    : Array.isArray(row?.mediaDescriptions)
      ? row.mediaDescriptions.map(item=>typeof item==='string'?{mediaDescription:item}:item)
      : [];

  const trustedInlineUrl=value=>{
    const url=String(value||'').trim();
    return /^(data:image\/|blob:)/i.test(url)?url:'';
  };

  const items=raw.map((item,idx)=>{
      if(typeof item==='string')return {id:`generated_media_${idx}`,url:'',desc:String(item).trim(),source:'description'};
      const desc=String(item?.mediaDescription??item?.description??item?.desc??'').trim();
      const url=trustedInlineUrl(item?.mediaUrl??item?.url??'');
      if(!desc && !url)return null;
      return {id:String(item?.id||`generated_media_${idx}`),url,desc:desc||'生活随手记录',source:url?'generated':'description',albumCategory:String(item?.albumCategory||item?.category||''),albumTags:Array.isArray(item?.albumTags)?item.albumTags:[],albumEraId:String(item?.albumEraId||item?.eraId||'')};
    })
    .filter(Boolean)
    .slice(0,4);

  if(items.length)return items;
  const fallbackDesc=String(row?.mediaDescription||row?.content?.mediaDescription||row?.content||'生活随手记录').trim() || '生活随手记录';
  return [{id:'generated_media_0',url:trustedInlineUrl(row?.mediaUrl||''),desc:fallbackDesc,source:'description'}];
}

function makeGeneratedFeedPost(row,actorId,type,index=0){
  const caption=normalizeHomeFeedGeneratedCaption(row);
  const sourceLanguage=String(caption.sourceLanguage||row?.actor?.language||publicIdentityRegistry?.[actorId]?.language||'zh').trim()||'zh';
  const metrics=row?.metrics||{};
  const explicitTags=normalizeGeneratedEnglishTags(row?.tags||[]);
  const inlineTags=normalizeGeneratedEnglishTags((String(caption.rawCaptionOriginal||'').match(/(^|\s)#[^\s#]+/g)||[]).map(tag=>String(tag||'').trim()));
  const tags=[...new Set([...explicitTags,...inlineTags])];
  if(!tags.length)tags.push('#daily');
  const cleanCaption=caption.captionOriginal;
  const parts=splitGeneratedCaptionText(cleanCaption);
  const initialComments=Array.isArray(row?.initialComments)?row.initialComments:(Array.isArray(row?.comments)?row.comments:[]);
  const id=`feed_ai_${Date.now()}_${index}_${Math.random().toString(36).slice(2,5)}`;
  const actorRegion=String(row?.actor?.region||row?.region||row?.country||'').trim();
  const locationLabel=normalizeAIGeneratedCityLocationLabel(row?.location||row?.actor?.location||'',sourceLanguage,cleanCaption,actorRegion);
  let mediaItems=normalizeGeneratedMediaItems(row);
  mediaItems=typeof resolveGeneratedMediaItemsWithAlbum==='function'?resolveGeneratedMediaItemsWithAlbum(actorId,mediaItems):mediaItems;
  const primaryMedia=mediaItems[0]||{url:'',desc:'生活随手记录',source:'description'};
  const post={
    id,type,followed:type!=='stranger',author:actorId,avatar:getIdentityMeta(actorId).initial,sub:locationLabel,
    mediaClass:`m${1+(index%4)}`,mediaType:'image',
    mediaText:String(primaryMedia.desc||'生活随手记录'),
    mediaDescription:String(primaryMedia.desc||'生活随手记录'),
    mediaUrl:String(primaryMedia.url||''),
    mediaItems,
    mediaCarouselIndex:0,
    mediaFlipped:false,
    mediaSource:mediaItems.some(x=>x.source==='album_matched')?(mediaItems.every(x=>x.source==='album_matched')?'album':'mixed'):(primaryMedia.generatedRequested?'generated_pending':primaryMedia.url?'generated':'description'),
    likes:normalizeGeneratedMetric(metrics.likes??row?.likes,28,2600),
    comments:Math.max(initialComments.length,normalizeGeneratedMetric(metrics.comments??row?.comments,8,96)),
    reposts:normalizeGeneratedMetric(metrics.reposts??row?.reposts,1,42),
    shares:normalizeGeneratedMetric(metrics.shares??row?.shares,1,78),
    liked:false,reposted:false,expanded:false,translated:false,homeTranslationOpen:false,
    feedCaptionZh:cleanCaption,
    feedOriginalText:'',
    feedSourceLanguage:sourceLanguage,
    feedShowingOriginal:false,
    captionOriginal:cleanCaption,
    captionTranslation:'',
    homeCaptionOriginal:cleanCaption,
    homeCaptionTranslation:'',
    captionShort:parts.short?` ${escapeDMCardHTML(parts.short)}`:'',
    captionLong:parts.long?` ${escapeDMCardHTML(parts.long)}`:'',
    tags,
    translation:'',sourceLanguage,location:locationLabel,generated:true
  };
  ensurePostFallbackDeck(post,posts.length+index);
  return post;
}
function recordGeneratedFeedPublish(actorId,post){
  if(!actorId||!post||typeof recordSocialEvent!=='function')return;
  const caption=ensureHomeFeedCaptionModel(post).chinese;
  const media=String(post.mediaDescription||post.mediaText||'').trim();
  const mentionMeta=detectFormalActorMentions(`${caption} ${media}`);
  if(!isFormalSocialActor(actorId) && !mentionMeta.length)return;
  const summary=[
    `${socialActorName(actorId)}发布了一条 IG 动态。`,
    caption?`文案：“${compactMemoryText(caption,160)}”`:'',
    media?`配图：${compactMemoryText(media,180)}`:''
  ].filter(Boolean).join(' ');
  recordSocialEvent({
    type:'feed_publish',
    actorId,
    targetIds:[],
    contentId:post.id,
    contentType:'feed',
    contentOwnerId:actorId,
    relatedActorIds:mentionMeta.map(row=>row.actorId),
    text:caption,
    visibility:'public',
    payload:{
      mentionMeta,
      mediaDescription:media,
      caption,
      metrics:{
        likes:Number(post.likes)||0,
        comments:Number(post.comments)||0,
        reposts:Number(post.reposts)||0,
        shares:Number(post.shares)||0
      },
      generated:true
    },
    summary
  },{knownActorIds:isFormalSocialActor(actorId)?[actorId,'user']:[],learnedVia:'current_feed'});
}
function rollINSFeedMediaCounts(count){
  const total=Math.max(1,Number(count)||1);
  const weighted=[1,1,1,2,2,3,4];
  const counts=Array.from({length:total},()=>weighted[Math.floor(Math.random()*weighted.length)]);
  if(total>=3){
    if(counts.every(n=>n===1))counts[Math.floor(Math.random()*total)]=2+Math.floor(Math.random()*2);
    if(counts.every(n=>n>1))counts[Math.floor(Math.random()*total)]=1;
  }
  return counts;
}
function buildINSFeedMediaPlanPrompt(counts=[]){
  if(!Array.isArray(counts)||!counts.length)return '';
  return '本批 IG 图片数量计划（必须严格按输出 item 顺序执行）：'+counts.map((n,i)=>`第${i+1}条=${n}张`).join('；')+'。多图时每张必须是不同画面/细节并分别返回独立 mediaDescription，禁止复制同一描述。';
}
function getINSProfileLocation(actorRef){
  const id=normalizeSocialActorId(actorRef);
  if(id==='user')return String(userProfileState?.location||'').trim();
  const key=typeof resolveCharProfileKey==='function'?resolveCharProfileKey(id):id;
  return String(charProfileState?.profiles?.[key]?.location||dmProfiles?.[key]?.location||'').trim();
}
function buildINSActorLocationPrompt(actorIds=[]){
  const rows=[...new Set((actorIds||[]).map(normalizeSocialActorId).filter(Boolean))]
    .map(id=>{const location=getINSProfileLocation(id);if(!location)return '';const meta=getIdentityMeta(id);return `@${meta.handle||id} 当前主页地点：${location}`;})
    .filter(Boolean);
  if(!rows.length)return '';
  return '生成 IG / Reels 时先读取以下账号主页的当前地点。地点是人物当前公开位置上下文；如输出 location，请转换/保持为英文城市级 City·Country 格式，不要输出社区/区/街道/店名等细地点，也不要无理由改去其他城市：\n'+rows.join('\n');
}

async function runINSRefreshStrangers(){
  const btn=document.getElementById('feedRefreshStrangersBtn');
  if(btn?.disabled)return;
  const prompt=document.getElementById('feedBatchPrompt')?.value.trim()||'';
  const requestedMediaCounts=rollINSFeedMediaCounts(4);
  const mediaPlanPrompt=buildINSFeedMediaPlanPrompt(requestedMediaCounts);
  setINSGenerationButtonBusy(btn,true,'生成中…');
  try{
    const result=await callNiniINSFeedSinglePass(INS_AI_TASKS.HOME_STRANGERS,{
      ownerId:'user',surface:'home_strangers',prompt:[prompt,mediaPlanPrompt].filter(Boolean).join('\n\n'),
      extra:{
        batchSize:4,globalPool:true,requestedMediaCounts,
        preferredRegions:['Korea','Japan','English-speaking regions','Hong Kong','Macau','Taiwan'],weightedPreference:true,
        includeInitialComments:true,initialCommentCount:5,
        requireEngagementMetrics:true,forbidCurrentUserInComments:true,
        forbidHashtags:false,diagnosticBuild:'5.0.16-home-strangers'
      }
    });
    if(!result.ok)throw new Error(result.reason||'陌生人动态生成失败');
    const items=getGeneratedItems(result.data);
    if(!items.length)throw new Error('AI 没有返回陌生人动态 items');

    const jobs=items.slice(0,6).map((row,index)=>{
      const handle=registerGeneratedPublicIdentity(row,index);
      const post=makeGeneratedFeedPost(row,handle,'stranger',index);
      post.generatedStranger=true;
      post.followed=false;
      recordGeneratedFeedPublish(handle,post);
      const initialComments=Array.isArray(row?.initialComments)
        ? row.initialComments.slice(0,5)
        : (Array.isArray(row?.comments)?row.comments.slice(0,5):[]);
      return {post,ownerId:handle,comments:initialComments};
    });
    const fresh=jobs.map(job=>job.post);
    posts.unshift(...fresh);

    jobs.forEach(job=>{
      commentsByPost[job.post.id]=[];
      applyGeneratedPublicCommentBatch({surface:'feed',contentId:job.post.id,ownerId:job.ownerId,comments:job.comments});
    });

    // Do not expose a newly refreshed stranger post until its visible comment sheet has 5 real rows.
    await Promise.all(jobs.map(job=>
      ensurePublicCommentFloor('feed',job.post.id,5)
        .catch(err=>console.warn('[INS] stranger initial comment top-up failed',job.post.id,err))
    ));
    jobs.forEach(job=>{
      const visible=(commentsByPost[job.post.id]||[]).length;
      job.post.comments=Math.max(Number(job.post.comments)||0,visible);
    });

    persistINSFeedGeneratedState();
    void flushINSFeedPersistence();
    renderFeed();
    closeFeedGlass();
  }catch(error){
    alert('刷新陌生人动态失败：'+(error?.message||error));
  }finally{
    setINSGenerationButtonBusy(btn,false,'','刷新陌生人');
  }
}

async function runINSCharFeedGeneration(){
  const selected=getSelectedFeedChars().filter(id=>isFormalSocialActor(id));
  if(!selected.length){alert('请先在“绑定角色”中绑定至少一个角色，再选择角色');return;}
  const btn=document.getElementById('feedCharsPostBtn');
  if(btn?.disabled)return;
  const prompt=document.getElementById('feedBatchPrompt')?.value.trim()||'';
  const locationPrompt=buildINSActorLocationPrompt(selected);
  setINSGenerationButtonBusy(btn,true,'生成中…');
  try{
    const feedOwnerId=selected.length===1?selected[0]:'user';
    const result=await callNiniINSFeedSinglePass(INS_AI_TASKS.FEED_GENERATE,{
      actorIds:selected,ownerId:feedOwnerId,surface:'feed',prompt:composeCharGenerationPrompt({actorIds:selected,surface:'feed',batchPrompt:prompt,extraPrompt:locationPrompt}),
      extra:{
        requestedCount:selected.length,onePerActor:true,freeMediaPlan:true,
        includeInitialComments:true,initialCommentCount:5,
        requireEngagementMetrics:true,forbidCurrentUserInComments:true,
        diagnosticBuild:'5.1-feed',
        ownerMode:selected.length===1?'selected_actor':'shared_batch'
      }
    });
    if(!result.ok)throw new Error(result.reason||'角色动态生成失败');
    const items=getGeneratedItems(result.data);
    if(!items.length)throw new Error('AI 没有返回角色动态 items');

    const made=[];
    const commentJobs=[];
    items.forEach((row,index)=>{
      const actorId=resolveGeneratedActorId(row,selected,index);
      if(!actorId||!selected.includes(actorId))return;
      const postType=(typeof isFixedNPCHandle==='function'&&isFixedNPCHandle(actorId))?'npc':'char';
      const post=makeGeneratedFeedPost(row,actorId,postType,index);
      post.followed=true;
      made.push(post);
      recordGeneratedFeedPublish(actorId,post);
      commentJobs.push({post,ownerId:actorId,comments:Array.isArray(row?.initialComments)?row.initialComments.slice(0,5):[]});
    });
    if(!made.length)throw new Error('AI 返回的人物无法匹配到已绑定角色');

    posts.unshift(...made);
    commentJobs.forEach(job=>{
      applyGeneratedPublicCommentBatch({surface:'feed',contentId:job.post.id,ownerId:job.ownerId,comments:job.comments});
      queueMicrotask(()=>void ensurePublicCommentFloor('feed',job.post.id,5).catch(err=>console.warn('[INS] Feed initial comment top-up failed',err)));
    });
    persistINSFeedGeneratedState();
    void flushINSFeedPersistence();
    renderFeed();closeFeedGlass();
  }catch(error){
    alert('生成 IG 动态失败（v5.1）\n\n'+(error?.message||error));
  }finally{
    setINSGenerationButtonBusy(btn,false,'','发 IG 动态');
    resetFeedPublishActionSelection();
  }
}

function resolveGeneratedStoryItemsWithAlbum(actorId,rawItems=[]){const normalized=(rawItems||[]).slice(0,4).map((item,index)=>({id:`story_ai_${actorId}_${Date.now()}_${index}`,type:item?.type==='video'?'video':'image',time:'刚刚',description:String(item?.mediaDescription||item?.description||'随手 Story'),mediaUrl:String(item?.mediaUrl||''),duration:Number(item?.duration)||5200,liked:false,generated:true,albumCategory:String(item?.albumCategory||item?.category||''),albumTags:Array.isArray(item?.albumTags)?item.albumTags:[],albumEraId:String(item?.albumEraId||item?.eraId||'')}));const imgs=normalized.filter(x=>x.type==='image'),resolved=typeof resolveGeneratedMediaItemsWithAlbum==='function'?resolveGeneratedMediaItemsWithAlbum(actorId,imgs.map(x=>({id:x.id,url:x.mediaUrl,desc:x.description,source:x.mediaUrl?'generated':'description',albumCategory:x.albumCategory,albumTags:x.albumTags,albumEraId:x.albumEraId}))):[];let p=0;return normalized.map(x=>{if(x.type!=='image')return x;const r=resolved[p++]||{};return {...x,mediaUrl:r.url||'',linkedAlbumId:r.linkedAlbumId||'',mediaSource:r.source||'description',generatedRequested:!!r.generatedRequested,albumCategory:r.albumCategory||x.albumCategory,albumTags:r.albumTags||x.albumTags,albumEraId:r.albumEraId||x.albumEraId};});}
