function checkINSAutoPublishTasks(){
  const now=Date.now();
  (typeof getRelationshipActors==='function'?getRelationshipActors():[]).filter(actor=>actor&&actor.id&&actor.id!=='user'&&isFormalSocialActor(actor.id)).forEach(actor=>{
    const state=ensureCharActivePublish(actor.id);if(!state)return;
    ['feed','story','reels'].forEach(surface=>{
      const cfg=state[surface];if(!cfg.enabled)return;
      if(!cfg.nextAt){cfg.nextAt=now+randomCharActiveInterval(cfg.intervalMin);saveJSONLocalState(CHAR_ACTIVE_PUBLISH_STORAGE_KEY,charActivePublishState);return;}
      if(now<cfg.nextAt)return;
      const busyKey=`${actor.id}:${surface}`;if(charAutoPublishBusy.has(busyKey))return;
      cfg.nextAt=now+randomCharActiveInterval(cfg.intervalMin);saveJSONLocalState(CHAR_ACTIVE_PUBLISH_STORAGE_KEY,charActivePublishState);
      charAutoPublishBusy.add(busyKey);
      Promise.resolve(runINSAutoPublishSurface(actor.id,surface)).catch(error=>console.warn('[INS] 主动发布失败',actor.id,surface,error)).finally(()=>charAutoPublishBusy.delete(busyKey));
    });
  });
}
function startINSAutoPublishTimer(){
  if(window.__niniINSAutoPublishStarted)return;
  window.__niniINSAutoPublishStarted=true;
  setInterval(checkINSAutoPublishTasks,CHAR_ACTIVE_CHECK_MS);
  setTimeout(checkINSAutoPublishTasks,3000);
}

// Capture-phase delegation: more reliable inside Roche mobile WebView after dynamic repaint.
document.addEventListener('click',event=>{
  const chip=event.target.closest?.('.feed-char-chip[data-feed-char]');
  if(chip){event.preventDefault();event.stopPropagation();chip.classList.toggle('on');return;}
  const action=event.target.closest?.('[data-ins-feed-action]');
  if(!action)return;
  event.preventDefault();event.stopPropagation();
  const type=action.dataset.insFeedAction;
  if(type==='refresh_strangers')void runINSRefreshStrangers();
  else if(type==='char_post'){resetFeedPublishActionSelection();void runINSCharFeedGeneration();}
  else if(type==='char_story'){resetFeedPublishActionSelection();void runINSCharStoryGeneration();}
},{capture:true});


/* ===== v1.15.22 per-post menu/editor behavior ===== */
let activePostMenuIndex = null;
let postEditCarouselIndex = 0;
let postEditCarouselFlipped = false;
let postEditPointerStartX = null;
let postEditPointerStartY = null;

const postGlassDim = document.getElementById('postGlassDim');
const postActionGlass = document.getElementById('postActionGlass');
const postEditGlass = document.getElementById('postEditGlass');
const postEditCaption = document.getElementById('postEditCaption');
const postEditMediaDescription = document.getElementById('postEditMediaDescription');
const postEditMediaPreview = document.getElementById('postEditMediaPreview');
const postEditMediaTypeNote = document.getElementById('postEditMediaTypeNote');
const postEditSourceBadge = document.getElementById('postEditSourceBadge');
const postEditAlbumTools = document.getElementById('postEditAlbumTools');
const postEditCarouselCounter = document.getElementById('postEditCarouselCounter');
const postEditStrangerIdentity = document.getElementById('postEditStrangerIdentity');
const postEditDisplayName = document.getElementById('postEditDisplayName');
const postEditHandle = document.getElementById('postEditHandle');
const postEditLocation = document.getElementById('postEditLocation');

function closePostGlass(){
  postActionGlass?.classList.remove('show');
  postEditGlass?.classList.remove('show');
  document.getElementById('postDeleteConfirm')?.classList.remove('show');
  postGlassDim?.classList.remove('show');
}

function openPostMenu(index){
  activePostMenuIndex = index;
  closeFeedGlass?.();
  postEditGlass?.classList.remove('show');
  postActionGlass?.classList.add('show');
  postGlassDim?.classList.add('show');
}

function getPostAlbumAssetsForCurrentEdit(author){
  if(typeof isRocheCharacterHandle==='function' && !isRocheCharacterHandle(author)) return [];
  if(typeof getCharAlbumSelectableAssets==='function')return getCharAlbumSelectableAssets(author);
  const key=typeof resolveCharProfileKey==='function' ? resolveCharProfileKey(author) : author;
  const assets=(charAlbumPreviewData[key] || []).filter(asset=>!['generated','generated_favorite'].includes(String(asset?.kind||'')));
  return typeof filterCharAlbumAssetsByConfiguredPeriod==='function'
    ? filterCharAlbumAssetsByConfiguredPeriod(author,assets)
    : assets;
}

function getPostEditSourceMode(post){
  if(!post)return 'fallback';
  if(post.mediaSource==='album' && post.linkedAlbumId)return 'album';
  if(post.mediaSource==='generated')return 'generated';
  if(['upload','user_upload','url'].includes(String(post.mediaSource||'')))return 'upload';
  if(Array.isArray(post.mediaItems) && post.mediaItems.length){
    const hasUploaded=post.mediaItems.some(item=>['upload','user_upload','url'].includes(String(item?.source||'').toLowerCase()));
    if(hasUploaded)return 'upload';
  }
  return 'fallback';
}

function getPostEditCandidates(post){
  if(!post)return [];
  const mode=getPostEditSourceMode(post);
  if((post.mediaType||'image')==='video'){
    return [{id:'video_description',url:'',desc:post.mediaDescription||post.mediaText||'视频描述',kind:'video',source:'description'}];
  }
  if(mode==='album'){
    const assets=getPostAlbumAssetsForCurrentEdit(post.author).slice(0,4);
    return assets.map((asset,index)=>({
      id:asset.id,
      url:asset.url || INS_FEED_FALLBACK_MEDIA_POOL[index%INS_FEED_FALLBACK_MEDIA_POOL.length]?.url || '',
      desc:asset.desc || '相册素材',
      kind:'album',
      source:'album'
    }));
  }
  const items=ensurePostEditMediaItems(post);
  const deck=ensurePostFallbackDeck(post,activePostMenuIndex||0);
  return items.slice(0,4).map((item,index)=>({
    id:item.id||`media_${index}`,
    url:item.url||deck[index]?.url||'',
    desc:item.desc||'',
    draft:!!item.draft,
    kind:mode,
    source:item.source||post.mediaSource||''
  }));
}

function ensurePostEditMediaItems(post){
  if(!post || (post.mediaType||'image')==='video')return [];
  if(Array.isArray(post.mediaItems) && post.mediaItems.length){
    post.mediaItems=post.mediaItems.filter(item=>item && (item.url || item.desc || item.draft)).slice(0,4).map((item,index)=>({
      id:item.id||`media_${Date.now()}_${index}`,
      url:item.url||'',
      // v1.2.24: each carousel image owns its own description.
      // Only image 1 may inherit the old post-level description for legacy data.
      desc:String(item.desc||'') || (index===0?String(post.mediaDescription||post.mediaText||''):''),
      source:item.source||(['upload','user_upload','url'].includes(String(post.mediaSource||''))?'upload':post.mediaSource==='generated'?'generated':'description'),
      draft:!!item.draft
    }));
    return post.mediaItems;
  }
  const seeded=getPostMediaItems(post,activePostMenuIndex||0).filter(item=>item && (item.url || item.desc)).slice(0,4).map((item,index)=>({
    id:item.id||`media_${Date.now()}_${index}`,
    url:item.url||'',
    desc:String(item.desc||'') || (index===0?String(post.mediaDescription||post.mediaText||''):''),
    source:item.source||(['upload','user_upload','url'].includes(String(post.mediaSource||''))?'upload':post.mediaSource==='generated'?'generated':'description')
  }));
  post.mediaItems=seeded.length?seeded:[{id:`media_${Date.now()}`,url:'',desc:post.mediaDescription||post.mediaText||'',source:'description'}];
  return post.mediaItems;
}

function commitPostEditCurrentDescription(post){
  if(!post || !postEditMediaDescription || (post.mediaType||'image')==='video')return;
  if(getPostEditSourceMode(post)==='album')return;
  const items=ensurePostEditMediaItems(post);
  if(!items.length)return;
  const idx=Math.max(0,Math.min(postEditCarouselIndex,items.length-1));
  const value=postEditMediaDescription.value.trim();
  items[idx]={...items[idx],desc:value,draft:value?false:!!items[idx].draft,source:items[idx].source||(['upload','user_upload','url'].includes(String(post.mediaSource||''))?'upload':post.mediaSource==='generated'?'generated':'description')};
  post.mediaItems=items;
  post.mediaCarouselIndex=idx;
  // Keep legacy post-level fields aligned with the first image only.
  // Editing image 2-4 must never overwrite image 1's semantic description.
  const primaryDesc=String(items[0]?.desc||'');
  post.mediaDescription=primaryDesc;
  post.mediaText=primaryDesc;
}

function syncPostEditCarouselIndex(post){
  const candidates=getPostEditCandidates(post);
  if(!candidates.length){postEditCarouselIndex=0;return;}
  const mode=getPostEditSourceMode(post);
  if(mode==='album' && post.linkedAlbumId){
    const idx=candidates.findIndex(item=>item.id===post.linkedAlbumId);
    postEditCarouselIndex=idx>=0?idx:0;
    return;
  }
  const currentId=Array.isArray(post.mediaItems) && Number.isInteger(post.mediaCarouselIndex)?post.mediaItems[post.mediaCarouselIndex]?.id:'';
  const currentUrl=post.mediaUrl || post.fallbackMediaUrl || '';
  const idx=currentId?candidates.findIndex(item=>String(item.id||'')===String(currentId||'')):candidates.findIndex(item=>item.url===currentUrl);
  postEditCarouselIndex=idx>=0?idx:Math.min(postEditCarouselIndex,candidates.length-1);
}

function applyPostEditCandidate(post,candidate){
  if(!post || !candidate)return;
  const mode=getPostEditSourceMode(post);
  if(mode==='album'){
    post.linkedAlbumId=candidate.id;
    post.mediaSource='album';
    post.mediaUrl=candidate.kind==='album' && candidate.url && getPostAlbumAssetsForCurrentEdit(post.author).some(asset=>asset.id===candidate.id && asset.url)?candidate.url:'';
    if(candidate.desc){
      post.mediaDescription=candidate.desc;
      post.mediaText=candidate.desc;
      if(postEditMediaDescription)postEditMediaDescription.value=candidate.desc;
    }
    return;
  }
  const items=ensurePostEditMediaItems(post);
  const idx=items.findIndex(item=>String(item?.id||'')===String(candidate.id||''));
  const resolvedIdx=idx>=0?idx:Math.max(0,Math.min(postEditCarouselIndex,items.length-1));
  post.mediaCarouselIndex=resolvedIdx;
  post.linkedAlbumId='';
  if(mode==='upload'){
    post.mediaSource='user_upload';
    if(candidate.url)post.mediaUrl=candidate.url;
  }else if(mode==='generated'){
    post.mediaSource='generated';
    if(candidate.url)post.mediaUrl=candidate.url;
  }else{
    post.mediaSource='description';
    post.fallbackMediaUrl=candidate.url||post.fallbackMediaUrl;
    post.fallbackMediaId=candidate.id||post.fallbackMediaId;
  }
  if(postEditMediaDescription)postEditMediaDescription.value=candidate.draft?'':String(candidate.desc||'');
}

function renderPostEditCarousel(post){
  if(!postEditMediaPreview || !post)return;
  const candidates=getPostEditCandidates(post);
  if(!candidates.length){
    postEditMediaPreview.innerHTML=`<div class="post-edit-media-back"><span>这个角色的私人相册目前没有可用于 Matcher 的图片。</span></div>`;
    if(postEditCarouselCounter)postEditCarouselCounter.textContent='0 / 0';
    if(postEditMediaDescription)postEditMediaDescription.value='';
    return;
  }
  postEditCarouselIndex=(postEditCarouselIndex+candidates.length)%candidates.length;
  const candidate=candidates[postEditCarouselIndex];
  if(postEditCarouselCounter)postEditCarouselCounter.textContent=`${postEditCarouselIndex+1} / ${candidates.length}`;
  if(postEditCarouselFlipped || !candidate.url){
    const previewDesc=candidate.draft?'请填写这张图的图片描述':(candidate.desc||'暂无图片描述');
    postEditMediaPreview.innerHTML=`<div class="post-edit-media-back"><span>${escapeDMCardHTML(previewDesc)}</span></div>`;
  }else{
    postEditMediaPreview.innerHTML=`<img draggable="false" src="${escapeDMCardHTML(candidate.url)}" alt="动态候选图片">`;
  }
  applyPostEditCandidate(post,candidate);
}

function updatePostEditSourceUI(post){
  if(!post)return;
  const mediaType=post.mediaType||'image';
  const isVideo=mediaType==='video';
  const roche=typeof isRocheCharacterHandle==='function' && isRocheCharacterHandle(post.author);
  const mode=getPostEditSourceMode(post);
  const editableCount=Math.max(0,getPostEditCandidates(post).length);
  const fallbackBtn=document.getElementById('postEditUseFallback');
  const albumBtn=document.getElementById('postEditUseAlbum');
  const generatedBtn=document.getElementById('postEditUseGenerated');
  const uploadBtn=document.getElementById('postEditUseUpload');
  const genAction=document.getElementById('postEditGenerateImage');
  const uploadAction=document.getElementById('postEditChooseUpload');
  const addAction=document.getElementById('postEditAddMedia');
  const delAction=document.getElementById('postEditDeleteMedia');
  const sourceNote=document.getElementById('postEditSourceNote');
  [fallbackBtn,albumBtn,generatedBtn,uploadBtn].forEach(btn=>btn?.classList.remove('active'));
  if(mode==='album')albumBtn?.classList.add('active');
  else if(mode==='generated')generatedBtn?.classList.add('active');
  else if(mode==='upload')uploadBtn?.classList.add('active');
  else fallbackBtn?.classList.add('active');
  if(albumBtn)albumBtn.disabled=isVideo || !roche;
  if(fallbackBtn)fallbackBtn.disabled=isVideo;
  if(generatedBtn)generatedBtn.disabled=isVideo;
  if(uploadBtn)uploadBtn.disabled=isVideo;
  if(postEditAlbumTools)postEditAlbumTools.style.display=isVideo?'none':'block';
  if(postEditMediaTypeNote){
    postEditMediaTypeNote.textContent=isVideo?'当前是视频动态：只编辑文案和视频描述，不走相册图片 / 生图 / 上传图片。':'支持默认示例图、角色相册、生图与上传图片；可做 1–4 张图，每张图都有独立图片描述。';
  }
  if(postEditSourceBadge){
    postEditSourceBadge.textContent=isVideo?'当前来源：视频描述':mode==='album'?'当前来源：角色私人相册':mode==='generated'?'当前来源：按描述生图':mode==='upload'?'当前来源：上传图片 + 图片描述':'当前来源：默认示例图 + 图片描述';
  }
  if(sourceNote){
    sourceNote.textContent=mode==='album'?'左右滑动浏览该角色相册候选；当前停留的卡片就是这条动态选择的相册素材。':mode==='generated'?'会直接调用 Roche 当前生图接口，用这张图的图片描述生成真实图片；插件内未单独配置时，默认继承 Roche 生图配置。':mode==='upload'?'上传模式支持 1–4 张图；你可以继续追加图片，也可以单独修改当前这张的描述。':'默认图片只是视觉占位；现在同一条动态支持 1–4 张图，每张图都可以写独立图片描述。';
  }
  if(genAction)genAction.classList.toggle('show',mode==='generated' && !isVideo);
  if(uploadAction)uploadAction.classList.toggle('show',mode==='upload' && !isVideo);
  if(addAction){addAction.classList.toggle('show',!isVideo && mode!=='album');addAction.disabled=editableCount>=4;addAction.textContent=mode==='upload'?'新增图':'新增图';}
  if(delAction){delAction.classList.toggle('show',!isVideo && mode!=='album');delAction.disabled=editableCount<=1;}
}

function renderPostEditAssetOptions(post){
  if(!post)return;
  syncPostEditCarouselIndex(post);
  updatePostEditSourceUI(post);
  renderPostEditCarousel(post);
}

function openPostEditor(){
  const post=posts[activePostMenuIndex];
  if(!post)return;
  const feedCaption=ensureHomeFeedCaptionModel(post).chinese;
  postEditCaption.value=[feedCaption,normalizeFeedPostTags(post.tags||[]).join(' ')].filter(Boolean).join(' ');
  const editableStranger=!!(post.generatedStranger && post.type==='stranger');
  postEditStrangerIdentity?.classList.toggle('show',editableStranger);
  if(editableStranger){const meta=getIdentityMeta(post.author);if(postEditDisplayName)postEditDisplayName.value=meta.name||post.author;if(postEditHandle)postEditHandle.value=meta.handle||post.author;if(postEditLocation)postEditLocation.value=post.location||post.sub||'';}
  ensurePostFallbackMedia(post,activePostMenuIndex||0);
  const editItems=ensurePostEditMediaItems(post);
  postEditCarouselIndex=Math.max(0,Math.min(Number(post.mediaCarouselIndex)||0,Math.max(0,(editItems.length||1)-1)));
  if(postEditMediaDescription)postEditMediaDescription.value=String(editItems[postEditCarouselIndex]?.desc||'');
  postEditCarouselFlipped=false;
  renderPostEditAssetOptions(post);
  postActionGlass.classList.remove('show');
  postEditGlass.classList.add('show');
  postEditGlass.scrollTop=0;
}

function deleteActivePost(){
  if(activePostMenuIndex===null || !posts[activePostMenuIndex])return;
  const post=posts[activePostMenuIndex];
  document.getElementById('postDeleteConfirmCopy').textContent='删除 @'+post.author+' 的这条动态后，它会立即从当前 Feed 中移除。';
  postActionGlass?.classList.remove('show');
  document.getElementById('postDeleteConfirm')?.classList.add('show');
  postGlassDim?.classList.add('show');
}
function cancelDeleteActivePost(){document.getElementById('postDeleteConfirm')?.classList.remove('show');postGlassDim?.classList.remove('show');}
function confirmDeleteActivePost(){
  if(activePostMenuIndex===null || !posts[activePostMenuIndex])return;
  const post=posts[activePostMenuIndex];
  const feed=document.getElementById('feed');
  const oldScroll=feed?feed.scrollTop:0;
  posts.splice(activePostMenuIndex,1);
  if(post?.id && commentsByPost[post.id])delete commentsByPost[post.id];
  if(typeof persistINSFeedGeneratedState==='function')persistINSFeedGeneratedState();
  activePostMenuIndex=null;
  document.getElementById('postDeleteConfirm')?.classList.remove('show');
  postGlassDim?.classList.remove('show');
  renderFeed();
  if(feed){requestAnimationFrame(()=>{feed.scrollTop=Math.max(0,Math.min(oldScroll,feed.scrollHeight-feed.clientHeight));});}
}

function applyGeneratedStrangerIdentityEdit(post){
  if(!post || !post.generatedStranger || post.type!=='stranger')return;
  const oldHandle=String(post.author||'').replace(/^@/,'');
  const oldMeta=publicIdentityRegistry[oldHandle]||getIdentityMeta(oldHandle);
  const newHandle=String(postEditHandle?.value||oldHandle).replace(/^@/,'').trim()||oldHandle;
  const newName=String(postEditDisplayName?.value||oldMeta.name||newHandle).trim()||newHandle;
  const newLocation=normalizeGeneratedLocationLabel(postEditLocation?.value||post.location||post.sub||'',post.sourceLanguage||'',post.captionShort||'',oldMeta.region||'') || String(postEditLocation?.value||'').trim();
  const next={...oldMeta,handle:newHandle,name:newName,avatarUrl:STRANGER_AVATAR_URL,location:newLocation};
  if(oldHandle!==newHandle)delete publicIdentityRegistry[oldHandle];
  publicIdentityRegistry[newHandle]=next;
  post.author=newHandle;
  post.avatar=next.initial||String(newName||'?').slice(0,1).toUpperCase();
  post.location=newLocation;
  post.sub=newLocation;
}

function saveActivePostEdit(){
  const post=posts[activePostMenuIndex];
  if(!post)return;
  const caption=postEditCaption.value.trim();
  const mediaDesc=postEditMediaDescription.value.trim();
  applyGeneratedStrangerIdentityEdit(post);
  commitPostEditCurrentDescription(post);
  const parsedCaption=splitFeedEditorCaptionAndTags(caption);
  const canonicalCaption=stripGeneratedCaptionHashtags(caption).trim();
  const captionChanged=canonicalCaption!==String(post.feedCaptionZh||post.captionOriginal||'').trim();
  post.feedCaptionZh=canonicalCaption;
  post.captionOriginal=canonicalCaption;
  post.homeCaptionOriginal=canonicalCaption;
  post.captionShort=parsedCaption.parts.short?' '+escapeDMCardHTML(parsedCaption.parts.short):'';
  post.captionLong=parsedCaption.parts.long?' '+escapeDMCardHTML(parsedCaption.parts.long):'';
  post.tags=parsedCaption.tags;
  post.expanded=false;
  if(captionChanged){
    post.feedOriginalText='';
    post.feedShowingOriginal=false;
    delete homeFeedTranslationCache[String(post.id||'')];
    homeFeedTranslationRuntime.delete(String(post.id||''));
    persistHomeFeedTranslationCache();
  }
  if((post.mediaType||'image')==='image'){
    if(post.mediaSource==='album' && post.linkedAlbumId){
      const desc=storyAlbumDesc(post.author,post.linkedAlbumId);
      if(desc && !mediaDesc)post.mediaDescription=desc;
      post.mediaItems=[];
    }else if(post.mediaSource==='generated'){
      post.linkedAlbumId='';
      ensurePostEditMediaItems(post);
      const items=post.mediaItems.filter(item=>item && (item.url || item.desc)).slice(0,4);
      post.mediaItems=items;
      post.mediaUrl=items[Math.max(0,Math.min(Number(post.mediaCarouselIndex)||0,items.length-1))]?.url || items[0]?.url || '';
      ensurePostFallbackMedia(post,activePostMenuIndex||0);
    }else if(getPostEditSourceMode(post)==='upload'){
      post.linkedAlbumId='';
      post.mediaSource='user_upload';
      const items=ensurePostEditMediaItems(post).filter(item=>item && (item.url || item.desc)).slice(0,4);
      if(items.length){post.mediaItems=items.map(item=>({...item,source:'upload',draft:false}));post.mediaUrl=items[Math.max(0,Math.min(Number(post.mediaCarouselIndex)||0,items.length-1))]?.url || items[0].url || '';}
    }else{
      post.linkedAlbumId='';
      post.mediaSource='description';
      const items=ensurePostEditMediaItems(post).filter(item=>item && (item.url || item.desc)).slice(0,4);
      post.mediaItems=items.map(item=>({...item,source:'description',draft:false}));
      post.mediaUrl='';
      ensurePostFallbackMedia(post,activePostMenuIndex||0);
    }
    // v1.2.24: keep old single-description fields as an image-1 compatibility mirror.
    if(post.mediaSource!=='album'){
      const primaryDesc=String(post.mediaItems?.[0]?.desc||'');
      post.mediaDescription=primaryDesc;
      post.mediaText=primaryDesc;
    }
  }else{post.mediaSource='description';post.linkedAlbumId='';}
  post.mediaFlipped=false;
  closePostGlass();
  renderFeed();
  renderUserProfile?.();
}

function setPostEditSource(mode){
  const post=posts[activePostMenuIndex];
  if(!post || (post.mediaType||'image')==='video')return;
  commitPostEditCurrentDescription(post);
  const roche=typeof isRocheCharacterHandle==='function' && isRocheCharacterHandle(post.author);
  if(mode==='album'){
    if(!roche){alert('固定 NPC / 非 Roche 账号不调用私人相册 Matcher');return;}
    const assets=getPostAlbumAssetsForCurrentEdit(post.author);
    if(!assets.length){alert('这个角色的私人相册还没有可用素材');return;}
    post.mediaSource='album';post.mediaUrl='';post.mediaItems=[];
    if(!post.linkedAlbumId || !assets.some(asset=>asset.id===post.linkedAlbumId))post.linkedAlbumId=assets[0].id;
  }else if(mode==='generated'){
    post.mediaSource='generated';post.linkedAlbumId='';ensurePostEditMediaItems(post);if(!post.mediaUrl)post.mediaUrl=post.mediaItems[post.mediaCarouselIndex||0]?.url||'';
  }else if(mode==='upload'){
    post.mediaSource='user_upload';post.linkedAlbumId='';ensurePostEditMediaItems(post);if(!(Array.isArray(post.mediaItems) && post.mediaItems.some(item=>item && item.url)) && !post.mediaUrl)requestPostUploadPicker();
  }else{
    post.mediaSource='description';post.linkedAlbumId='';post.mediaUrl='';ensurePostEditMediaItems(post);post.mediaItems=post.mediaItems.map(item=>({...item,source:'description'}));ensurePostFallbackMedia(post,activePostMenuIndex||0);
  }
  postEditCarouselFlipped=false;
  postEditCarouselIndex=Math.max(0,Math.min(Number(post.mediaCarouselIndex)||0,Math.max(0,(getPostEditCandidates(post).length||1)-1)));
  renderPostEditAssetOptions(post);
}

function requestPostUploadPicker(){document.getElementById('postEditUploadInput')?.click();}
async function handlePostEditUploadFiles(fileList){
  const post=posts[activePostMenuIndex];
  if(!post)return;
  commitPostEditCurrentDescription(post);
  const existing=getPostEditSourceMode(post)==='upload'?ensurePostEditMediaItems(post).filter(item=>item && item.url).slice(0,4):[];
  const room=Math.max(0,4-existing.length);
  const files=[...(fileList||[])].filter(file=>file && /^image\//.test(String(file.type||''))).slice(0,room||4);
  if(!files.length)return;
  const readAsDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=reject;reader.readAsDataURL(file);});
  const urls=await Promise.all(files.map(readAsDataUrl));
  const appended=urls.map((url,index)=>({id:`upload_${Date.now()}_${index}`,url,desc:'',source:'upload',draft:true}));
  post.mediaItems=[...existing,...appended].slice(0,4);
  post.mediaCarouselIndex=Math.max(0,Math.min(existing.length,post.mediaItems.length-1));
  post.mediaUrl=post.mediaItems[post.mediaCarouselIndex]?.url||post.mediaItems[0]?.url||'';
  post.mediaSource='user_upload';
  post.linkedAlbumId='';
  post.uploadedFileNames=[...(post.uploadedFileNames||[]),...files.map(file=>file.name).filter(Boolean)].slice(0,4);
  const primaryDesc=String(post.mediaItems?.[0]?.desc||'');
  post.mediaDescription=primaryDesc;
  post.mediaText=primaryDesc;
  postEditCarouselIndex=post.mediaCarouselIndex;
  postEditCarouselFlipped=false;
  renderPostEditAssetOptions(post);
}

function addPostEditMediaSlot(){
  const post=posts[activePostMenuIndex];
  if(!post || (post.mediaType||'image')==='video')return;
  const mode=getPostEditSourceMode(post);
  if(mode==='album'){alert('角色相册模式不在这里手动增删；如需自由增删，请切到默认图片 / 生图 / 上传图片。');return;}
  if(mode==='upload'){requestPostUploadPicker();return;}
  commitPostEditCurrentDescription(post);
  const items=ensurePostEditMediaItems(post);
  if(items.length>=4){alert('一条动态最多 4 张图');return;}
  if(mode==='generated')post.mediaSource='description';
  items.push({id:`media_${Date.now()}`,url:'',desc:'',source:'description',draft:true});
  post.mediaItems=items;
  post.mediaCarouselIndex=items.length-1;
  postEditCarouselIndex=items.length-1;
  postEditCarouselFlipped=false;
  renderPostEditAssetOptions(post);
}

function deleteCurrentPostEditMedia(){
  const post=posts[activePostMenuIndex];
  if(!post || (post.mediaType||'image')==='video')return;
  const mode=getPostEditSourceMode(post);
  if(mode==='album'){alert('角色相册模式不在这里手动删图；如需自由删图，请先切换来源。');return;}
  commitPostEditCurrentDescription(post);
  const items=ensurePostEditMediaItems(post);
  if(items.length<=1){alert('至少保留 1 张图 / 1 段图像语义');return;}
  const idx=Math.max(0,Math.min(postEditCarouselIndex,items.length-1));
  items.splice(idx,1);
  post.mediaItems=items;
  post.mediaCarouselIndex=Math.max(0,Math.min(idx,items.length-1));
  postEditCarouselIndex=post.mediaCarouselIndex;
  if(mode==='upload'){post.mediaUrl=items[post.mediaCarouselIndex]?.url||items[0]?.url||'';}
  else if(mode==='generated' && !items.some(item=>item.url)){post.mediaSource='description';post.mediaUrl='';}
  ensurePostFallbackMedia(post,activePostMenuIndex||0);
  postEditCarouselFlipped=false;
  renderPostEditAssetOptions(post);
}

function shiftPostEditCarousel(delta){
  const post=posts[activePostMenuIndex];
  if(!post)return;
  commitPostEditCurrentDescription(post);
  const candidates=getPostEditCandidates(post);
  if(candidates.length<=1)return;
  postEditCarouselIndex=(postEditCarouselIndex+delta+candidates.length)%candidates.length;
  postEditCarouselFlipped=false;
  renderPostEditCarousel(post);
}

