/* ===== v1.2.25 flexible profile count display / numeric parsing ===== */
function normalizeINSCountDigits(value=''){
  return String(value??'').normalize('NFKC').trim();
}
function parseINSCountInput(value,fallback=0){
  const display=normalizeINSCountDigits(value);
  const safeFallback=Math.max(0,Number(fallback)||0);
  if(!display)return {display:String(safeFallback),numeric:safeFallback,parsed:true};

  const compact=display.replace(/[,_，\s]/g,'');
  const match=compact.match(/([+-]?(?:\d+(?:\.\d+)?|\.\d+))\s*(k|w|m|b|千|万|億|亿)?/i);
  if(!match)return {display,numeric:safeFallback,parsed:false};

  const base=Number(match[1]);
  if(!Number.isFinite(base))return {display,numeric:safeFallback,parsed:false};
  const suffix=String(match[2]||'').toLowerCase();
  const multiplier={k:1e3,w:1e4,m:1e6,b:1e9,'千':1e3,'万':1e4,'億':1e8,'亿':1e8}[suffix]||1;
  const numeric=Math.max(0,Math.round(base*multiplier));
  return {display,numeric,parsed:true};
}
function getINSCountDisplay(profile,key){
  const displayKey=key+'Display';
  const raw=profile?.[displayKey];
  if(raw!==undefined && raw!==null && String(raw).trim())return String(raw).trim();
  const numeric=Number(profile?.[key]);
  return Number.isFinite(numeric)?String(Math.max(0,numeric)):String(profile?.[key]??0);
}
function applyINSCountInput(profile,key,value){
  if(!profile||!key)return {display:'0',numeric:0,parsed:false};
  const current=Number(profile[key]);
  const parsed=parseINSCountInput(value,Number.isFinite(current)?current:0);
  profile[key]=parsed.numeric;
  profile[key+'Display']=parsed.display;
  return parsed;
}

