const profileContentDetailState={ownerRef:'',kind:'feed',selectedId:'',returnLabel:''};
function getProfileContentOwnerMeta(ref){
  if(ref==='user')return getIdentityMeta('user');
  return getIdentityMeta(ref);
}
function getFeedItemsForOwner(ref){
  if(ref==='user' || isINSCurrentUserIdentityRef(ref))return getUserOwnFeedPosts();
  const profileKey=resolveCharProfileKey(ref);
  if(charProfileState.profiles[profileKey])return getPostsForProfile(charProfileState.profiles[profileKey]);
  return posts.filter(p=>String(p.author||'')===String(ref||''));
}
function getReelItemsForOwner(ref){
  if(ref==='user' || isINSCurrentUserIdentityRef(ref))return getUserOwnReels();
  const profileKey=resolveCharProfileKey(ref);
  if(charProfileState.profiles[profileKey])return getReelsForProfile(charProfileState.profiles[profileKey]);
  return (reelsV15State.items||[]).filter(item=>String(item.author||'')===String(ref||''));
}
