function renderProfileContentDetail(scrollToSelected=true){
  const route=ensureProfileContentDetailRoute();
  const ownerRef=profileContentDetailState.ownerRef;
  const kind=profileContentDetailState.kind;
  const meta=getProfileContentOwnerMeta(ownerRef);
  const items=kind==='reels'?getReelItemsForOwner(ownerRef):getFeedItemsForOwner(ownerRef);
  route.querySelector('#pcdTitle').textContent='@'+(meta.handle||meta.name||ownerRef||'profile');
  route.querySelector('#pcdSubtitle').textContent=kind==='reels'?'Reels':'IG 动态';
  const scroll=route.querySelector('#pcdScroll');
  if(!items.length){
    scroll.innerHTML='<div class="route-empty"><strong>这里还没有内容</strong></div>';
    return;
  }
  scroll.innerHTML=items.map(item=>{
    const identity=getIdentityMeta(item.author);
    const selected=String(item.id)===String(profileContentDetailState.selectedId);
    const repostFromUser=ownerRef==='user' && String(item.author||'')!=='user';
    if(kind==='reels'){
      const canTranslate=shouldOfferTranslation(item.caption||'',item.translation);
      return `<article class="pcd-card ${selected?'pcd-selected':''}" data-pcd-id="${escapeDMCardHTML(item.id)}">
        <div class="pcd-card-head">
          <div class="pcd-avatar" data-identity-avatar="${escapeDMCardHTML(item.author)}">${escapeDMCardHTML(identity.initial||'?')}</div>
          <div class="pcd-author"><strong>${escapeDMCardHTML(identity.name)}</strong><span>@${escapeDMCardHTML(identity.handle||item.author)}</span>${repostFromUser?'<div class="pcd-repost-note">来自你的转发</div>':''}</div>
        </div>
        <div class="pcd-media reel">${escapeDMCardHTML(item.videoDescription||'Reel')}</div>
        <div class="pcd-body">
          <div class="pcd-actions">
            <button class="pcd-action" data-pcd-like="reels">♡ ${fmtSocial(item.likes+(item.liked?1:0))}</button>
            <button class="pcd-action" data-pcd-comments="reels">评论 ${fmtSocial(item.comments)}</button>
            <button class="pcd-action" data-pcd-repost="reels">↻ ${fmtSocial(item.reposts+(item.reposted?1:0))}</button>
            <span>分享 ${fmtSocial(Number(item.shares)||0)}</span>
          </div>
          <div class="pcd-caption"><strong>${escapeDMCardHTML(identity.name)}</strong>${escapeDMCardHTML(item.caption||'')}</div>
          ${canTranslate?`<div class="pcd-translation-toggle" data-pcd-translate="${escapeDMCardHTML(item.id)}">${item.translated?'收起翻译':'查看翻译'}</div><div class="pcd-translation ${item.translated?'show':''}">${escapeDMCardHTML(item.translation||'')}</div>`:''}
        </div>
      </article>`;
    }
    const media=getPostCurrentMediaItem(item,posts.indexOf(item));
    const caption=[item.captionShort||'',item.captionLong||''].join('').trim();
    const canTranslate=shouldOfferTranslation(caption,item.translation);
    return `<article class="pcd-card ${selected?'pcd-selected':''}" data-pcd-id="${escapeDMCardHTML(item.id)}">
      <div class="pcd-card-head">
        <div class="pcd-avatar" data-identity-avatar="${escapeDMCardHTML(item.author)}">${escapeDMCardHTML(identity.initial||'?')}</div>
        <div class="pcd-author"><strong>${escapeDMCardHTML(identity.name)}</strong><span>@${escapeDMCardHTML(identity.handle||item.author)}</span>${repostFromUser?'<div class="pcd-repost-note">来自你的转发</div>':''}</div>
      </div>
      <div class="pcd-media feed ${media.url?'has-image':'text-only'}">${media.url?`<img src="${escapeDMCardHTML(media.url)}" alt="">`:escapeDMCardHTML(item.mediaDescription||item.mediaText||'IG 动态')}</div>
      <div class="pcd-body">
        <div class="pcd-actions">
          <button class="pcd-action" data-pcd-like="feed">♡ ${fmtSocial(item.likes+(item.liked?1:0))}</button>
          <button class="pcd-action" data-pcd-comments="feed">评论 ${fmtSocial(item.comments)}</button>
          <button class="pcd-action" data-pcd-repost="feed">↻ ${fmtSocial(item.reposts+(item.reposted?1:0))}</button>
          <span>分享 ${fmtSocial(item.shares)}</span>
        </div>
        <div class="pcd-caption"><strong>${escapeDMCardHTML(identity.name)}</strong>${caption}</div>
        ${canTranslate?`<div class="pcd-translation-toggle" data-pcd-translate="${escapeDMCardHTML(item.id)}">${item.translated?'收起翻译':'查看翻译'}</div><div class="pcd-translation ${item.translated?'show':''}">${escapeDMCardHTML(item.translation||'')}</div>`:''}
      </div>
    </article>`;
  }).join('');
  hydrateIdentityAvatars(scroll);
  if(scrollToSelected){
    requestAnimationFrame(()=>{
      const target=scroll.querySelector(`[data-pcd-id="${CSS.escape(String(profileContentDetailState.selectedId||''))}"]`);
      scroll.scrollTop=target ? Math.max(0,target.offsetTop) : 0;
      document.documentElement.scrollTop=0;
      document.body.scrollTop=0;
    });
  }
}

