function handleProfileContentDetailClick(event){
  const card=event.target.closest('[data-pcd-id]');
  if(!card)return;
  const id=card.dataset.pcdId;
  const kind=profileContentDetailState.kind;
  if(event.target.closest('[data-pcd-like]')){
    if(kind==='reels'){
      const item=getReelsV15Item(id);if(item)item.liked=!item.liked;
    }else{
      const post=posts.find(p=>p.id===id);if(post)post.liked=!post.liked;
    }
    renderProfileContentDetail(false);return;
  }
  if(event.target.closest('[data-pcd-repost]')){
    if(kind==='reels'){
      const item=getReelsV15Item(id);if(item)item.reposted=!item.reposted;
    }else{
      const post=posts.find(p=>p.id===id);if(post)post.reposted=!post.reposted;
    }
    renderUserProfile();renderProfileContentDetail(false);return;
  }
  if(event.target.closest('[data-pcd-translate]')){
    if(kind==='reels'){
      const item=getReelsV15Item(id);if(item)item.translated=!item.translated;
    }else{
      const post=posts.find(p=>p.id===id);if(post)post.translated=!post.translated;
    }
    renderProfileContentDetail(false);return;
  }
  if(event.target.closest('[data-pcd-comments]')){
    if(kind==='reels'){
      reelsV15State.activeId=id;reelsV15CommentReplyTo=null;const input=document.getElementById('reelsV15CommentInput');if(input)input.placeholder='添加评论…';renderReelsV15Comments();openReelsV15Sheet('reelsV15CommentSheet');
    }else openCommentsForPost(id);
  }
}

function renderUserProfile(){
  const topId = document.getElementById('userProfileTopId');
  const display = document.getElementById('userDisplayName');
  const handle = document.getElementById('userHandle');
  const location = document.getElementById('userProfileLocation');
  const bio = document.getElementById('userBio');
  const followers = document.getElementById('userFollowers');
  const following = document.getElementById('userFollowing');
  const count = document.getElementById('userPostCount');

  if(!topId) return;

  topId.textContent = userProfileState.id;
  display.textContent = userProfileState.displayName;
  handle.textContent = '@' + userProfileState.id;
  if(location){const text=String(userProfileState.location||'').trim();location.classList.toggle('show',!!text);const span=location.querySelector('span');if(span)span.textContent=text;}
  bio.innerHTML = escapeDMCardHTML(userProfileState.bio).replace(/\n/g,'<br>');
  followers.textContent = getINSCountDisplay(userProfileState,'followers');
  following.textContent = getINSCountDisplay(userProfileState,'following');
  count.textContent = getUserOwnFeedPosts().length + getUserOwnReels().length;
  applyUserAvatarVisual();
  hydrateIdentityAvatars(document);
  renderUserHighlights();

  const userTabs = [...document.querySelectorAll('.user-tab')];
  userTabs.forEach(btn=>{
    btn.classList.toggle('active', btn.dataset.userTab === userProfileState.activeTab);
  });
  const indicator = document.getElementById('userTabIndicator');
  const activeIndex = Math.max(0, userTabs.findIndex(btn => btn.dataset.userTab === userProfileState.activeTab));
  if(indicator){
    indicator.style.transform = `translateX(${activeIndex * 100}%)`;
  }

  renderUserProfileGrid(userProfileState.activeTab);
}


