function normalizeHomeFeedModelsEndpoint(url=''){
  const clean=String(url||'').trim().replace(/\/+$/,'');
  if(!clean)return '';
  return clean.replace(/\/chat\/completions$/i,'') + '/models';
}
async function refreshHomeFeedTranslationModels(){
  const url=String(document.getElementById('feedTranslationApiUrl')?.value||'').trim();
  const apiKey=String(document.getElementById('feedTranslationApiKey')?.value||'').trim();
  const select=document.getElementById('feedTranslationApiModel');
  if(!url||!apiKey){alert('先填写 Base URL 和 API Key');return;}
  if(select)select.innerHTML='<option value="">正在拉取模型...</option>';
  try{
    const res=await fetch(normalizeHomeFeedModelsEndpoint(url),{headers:{Authorization:'Bearer '+apiKey}});
    if(!res.ok)throw new Error('状态 '+res.status);
    const data=await res.json();
    const models=(Array.isArray(data?.data)?data.data:[])
      .map(item=>String(item?.id||'').trim())
      .filter(Boolean);
    if(!select)return;
    if(!models.length){
      select.innerHTML='<option value="">未获取到模型</option>';
      return;
    }
    const current=String(homeFeedTranslationApiSettings.model||'').trim();
    select.innerHTML=models.map(id=>`<option value="${escapeDMCardHTML(id)}">${escapeDMCardHTML(id)}</option>`).join('');
    if(current&&models.includes(current))select.value=current;
  }catch(error){
    if(select)select.innerHTML='<option value="">拉取失败，请检查 URL / Key</option>';
    alert('拉取模型失败：'+(error?.message||'未知错误'));
  }
}
function saveHomeFeedTranslationApiSettings(){
  const url=String(document.getElementById('feedTranslationApiUrl')?.value||'').trim().replace(/\/+$/,'');
  const apiKey=String(document.getElementById('feedTranslationApiKey')?.value||'').trim();
  const model=String(document.getElementById('feedTranslationApiModel')?.value||'').trim();
  if(!url||!apiKey||!model){alert('请完整填写 URL、API Key 和模型');return;}
  if(!/^https?:\/\//i.test(url)){alert('URL 需要以 http:// 或 https:// 开头');return;}
  homeFeedTranslationApiSettings={url,apiKey,model};
  persistHomeFeedTranslationApiSettings();
  updateHomeFeedTranslationApiDrawerLabel();
  closeHomeFeedTranslationApiSettings();
  alert('Feed 正文翻译 API 已保存');
}

function normalizeINSUserBindingPersona(raw={}){
  const id=String(raw?.id||raw?.personaId||raw?.handle||raw?.name||'').trim();
  const handle=String(raw?.handle||raw?.username||raw?.id||raw?.name||'').replace(/^@/,'').trim();
  const name=String(raw?.name||raw?.displayName||handle||id||'').trim();
  return {id:id||handle||name,handle:handle||id||name,name:name||handle||id,bio:String(raw?.bio||''),avatar:String(raw?.avatar||raw?.avatarUrl||''),active:!!raw?.active};
}
async function getAvailableINSUserBindingPersonas(){
  let list=[];
  try{if(window.NiniINSHost?.getAvailableUserPersonas){const raw=await window.NiniINSHost.getAvailableUserPersonas();if(Array.isArray(raw))list=raw;}}catch(error){console.warn('[INS] 获取可绑定 user persona 失败',error);}
  const current=normalizeINSUserBindingPersona({id:userProfileState.rochePersonaId||userProfileState.id,handle:userProfileState.id,name:userProfileState.displayName,bio:userProfileState.bio,avatar:userProfileState.avatarUrl||userProfileState.defaultAvatarUrl||'',active:true});
  const map=new Map();
  [current,...list.map(normalizeINSUserBindingPersona)].forEach(persona=>{if(!persona?.id && !persona?.handle)return;const key=String(persona.id||persona.handle);map.set(key,map.has(key)?{...map.get(key),...persona}:persona);});
  const items=[...map.values()];
  const activeKey=String(userProfileState.rochePersonaId||current.id||'');
  items.forEach(item=>{item.active=String(item.id||'')===activeKey || String(item.handle||'')===String(userProfileState.id||'');});
  return items;
}
function applyBoundINSUserPersona(rawPersona={}){
  const persona=normalizeINSUserBindingPersona(rawPersona);
  if(!persona.id && !persona.handle)return;
  userProfileState.rochePersonaId=persona.id||userProfileState.rochePersonaId||'';
  userProfileState.id=persona.handle||userProfileState.id;
  userProfileState.displayName=persona.name||userProfileState.displayName;
  userProfileState.bio=persona.bio || '';
  userProfileState.avatarUrl=persona.avatar || '';
  userProfileState.defaultAvatarUrl=persona.avatar || '';
  renderRocheHydratedIdentityUI?.();
  renderDMImportActorList?.();
  renderDMUserNpcHub?.();
  renderFeedShareDMRecipients?.();
  renderReelsV15DMRecipients?.();
  syncAllDMListPreviews?.();
  renderUserProfile?.();
  renderFeed?.();
  renderReelsV15?.();
  renderCreatePostCharChoices?.();
  hydrateIdentityAvatars(document);
}
async function renderINSUserIdentityBindingList(){
  const wrap=document.getElementById('identityBindList');
  if(!wrap)return;
  const personas=await getAvailableINSUserBindingPersonas();
  if(!personas.length){wrap.innerHTML='<div class="identity-bind-empty">还没有可切换的 user persona。</div>';return;}
  wrap.innerHTML=personas.map(persona=>{const avatarStyle=persona.avatar?` style="background-image:url(&quot;${escapeDMCardHTML(persona.avatar)}&quot;);"`:'';return `<div class="identity-bind-row"><div class="identity-bind-avatar"${avatarStyle}>${persona.avatar?'':escapeDMCardHTML((persona.name||persona.handle||'?').slice(0,1).toUpperCase())}</div><div class="identity-bind-copy"><div class="identity-bind-name">${escapeDMCardHTML(persona.name||persona.handle||persona.id)}</div><div class="identity-bind-handle">@${escapeDMCardHTML(persona.handle||persona.id)}</div><div class="identity-bind-meta">${persona.active?'当前绑定的 INS user 身份':'切换后，INS 里的 user 主页、头像、发帖身份都会一起切换。'}</div></div><button class="identity-bind-apply ${persona.active?'light':''}" type="button" data-bind-persona="${escapeDMCardHTML(persona.id)}">${persona.active?'已绑定':'切换'}</button></div>`;}).join('');
}
