async function switchINSBoundUserPersona(personaId){const targetId=String(personaId||'').trim();if(!targetId)return;const list=await getAvailableINSUserBindingPersonas();let persona=list.find(item=>String(item.id||'')===targetId) || list.find(item=>String(item.handle||'')===targetId);if(!persona)return;try{if(window.NiniINSHost?.setActiveUserPersona){const result=await window.NiniINSHost.setActiveUserPersona(targetId);if(result && typeof result==='object')persona=normalizeINSUserBindingPersona(result);}if(window.NiniINSHost?.getActiveUserPersona){const fresh=await window.NiniINSHost.getActiveUserPersona();if(fresh && typeof fresh==='object')persona=normalizeINSUserBindingPersona(fresh);}}catch(error){alert('切换绑定 user 身份失败：'+(error?.message||'未知错误'));return;}applyBoundINSUserPersona(persona);await renderINSUserIdentityBindingList();closeINSUserIdentityBindingSheet();}
