const INS_INTERFACE_SIZE_STORAGE_KEY='nini-ins-interface-size-v1';
const INS_INTERFACE_SIZE_DEFAULTS=Object.freeze({topSafe:44,bottomSafe:26});
function clampINSInterfaceSize(value,min,max,fallback){
  const number=Number(value);
  return Number.isFinite(number)?Math.min(max,Math.max(min,Math.round(number))):fallback;
}
function loadINSInterfaceSize(){
  try{
    const saved=JSON.parse(localStorage.getItem(INS_INTERFACE_SIZE_STORAGE_KEY)||'{}');
    return {
      topSafe:clampINSInterfaceSize(saved.topSafe,0,80,INS_INTERFACE_SIZE_DEFAULTS.topSafe),
      bottomSafe:clampINSInterfaceSize(saved.bottomSafe,0,56,INS_INTERFACE_SIZE_DEFAULTS.bottomSafe)
    };
  }catch(e){return {...INS_INTERFACE_SIZE_DEFAULTS};}
}
let insInterfaceSizeState=loadINSInterfaceSize();
function applyINSInterfaceSize(){
  const root=document.documentElement;
  if(!root?.style)return;
  root.style.setProperty('--ins-safe-top',insInterfaceSizeState.topSafe+'px');
  root.style.setProperty('--ins-safe-bottom',insInterfaceSizeState.bottomSafe+'px');
}
function persistINSInterfaceSize(){
  try{localStorage.setItem(INS_INTERFACE_SIZE_STORAGE_KEY,JSON.stringify(insInterfaceSizeState));}catch(e){}
}
function renderINSInterfaceSizeControls(){
  const topRange=document.getElementById('insTopSafeRange');
  const bottomRange=document.getElementById('insBottomSafeRange');
  const topValue=document.getElementById('insTopSafeValue');
  const bottomValue=document.getElementById('insBottomSafeValue');
  if(topRange)topRange.value=String(insInterfaceSizeState.topSafe);
  if(bottomRange)bottomRange.value=String(insInterfaceSizeState.bottomSafe);
  if(topValue)topValue.textContent=insInterfaceSizeState.topSafe+'px';
  if(bottomValue)bottomValue.textContent=insInterfaceSizeState.bottomSafe+'px';
}
function updateINSInterfaceSize(next){
  insInterfaceSizeState={
    topSafe:clampINSInterfaceSize(next.topSafe,0,80,insInterfaceSizeState.topSafe),
    bottomSafe:clampINSInterfaceSize(next.bottomSafe,0,56,insInterfaceSizeState.bottomSafe)
  };
  applyINSInterfaceSize();
  persistINSInterfaceSize();
  renderINSInterfaceSizeControls();
}
