function scrubINSImageSemanticCache(root){
  let count=0;
  const seen=new WeakSet();
  const walk=value=>{
    if(!value||typeof value!=='object'||seen.has(value))return;
    seen.add(value);
    if(Object.prototype.hasOwnProperty.call(value,'visionSummary') && value.visionSummary){value.visionSummary='';count++;}
    if(Object.prototype.hasOwnProperty.call(value,'visionStatus'))value.visionStatus='idle';
    if(Array.isArray(value)){value.forEach(walk);return;}
    Object.values(value).forEach(walk);
  };
  walk(root);
  return count;
}
async function clearNiniINSImageCache(){
  const count=[storyViewerData,storyArchive,storyCreateDraft].reduce((sum,root)=>sum+scrubINSImageSemanticCache(root),0);
  try{persistNiniStoryLifecycle?.();}catch(e){}
  try{
    if(window.caches&&typeof caches.keys==='function'){
      const keys=await caches.keys();
      await Promise.all(keys.filter(key=>/nini|instagram/i.test(String(key))).map(key=>caches.delete(key)));
    }
  }catch(e){}
  alert(`已清空 INS 图片缓存${count?`（${count} 条识图摘要）`:''}。私人相册、URL 照片和手机导入照片不会被删除。`);
}
function isNiniINSLocalStorageKey(key=''){
  return /^(nini-ins|nini_ins|niniInstagram|nini-instagram|niniIns)/i.test(String(key||''));
}
async function clearAllNiniINSData(){
  if(!confirm('这会清空 INS 的本地数据：私人相册、时期设置、角色生成偏好/主动频率、世界观提示词、Story 存档、Social Event / Knowledge，以及 INS DM 历史。Roche 本体的角色、聊天和记忆不会删除。\n\n继续吗？'))return;
  if(!confirm('最后确认：确定要把 INS 当作第一次安装重新开始吗？'))return;
  window.__NiniINSResetting=true;
  try{
    const keys=[];
    for(let i=0;i<localStorage.length;i++){
      const key=localStorage.key(i);if(isNiniINSLocalStorageKey(key))keys.push(key);
    }
    keys.forEach(key=>{try{localStorage.removeItem(key);}catch(e){}});
  }catch(e){}
  try{await window.NiniINSHost?.clearPluginPersistentData?.();}catch(e){console.warn('[INS] Roche storage reset failed',e);}
  alert('INS 数据已清空。现在会关闭插件；重新打开后就是干净的新开始。');
  try{await window.NiniINSHost?.closeAfterReset?.();}catch(e){}
}

