function findHighlightCellAtPoint(stripSelector,cellSelector,x,y){
  const strip=document.querySelector(stripSelector);
  if(!strip)return null;
  const stripRect=strip.getBoundingClientRect();
  if(x<stripRect.left-4 || x>stripRect.right+4 || y<stripRect.top-4 || y>stripRect.bottom+6) return null;

  const cells=[...strip.querySelectorAll(cellSelector)];
  return cells.find(cell=>{
    const r=cell.getBoundingClientRect();
    return x>=r.left-5 && x<=r.right+5 && y>=r.top-4 && y<=r.bottom+8;
  }) || null;
}

let lastHighlightPointerHandledAt=0;

function bindOneHighlightPointerFallback(scroll,stripSelector,cellSelector,idAttr,openFn,boundKey){
  if(!scroll || scroll.dataset[boundKey])return;
  scroll.dataset[boundKey]='1';

  let start=null;

  scroll.addEventListener('pointerdown',e=>{
    const cell=findHighlightCellAtPoint(stripSelector,cellSelector,e.clientX,e.clientY);
    if(!cell){
      start=null;
      return;
    }
    start={
      x:e.clientX,
      y:e.clientY,
      id:cell.getAttribute(idAttr),
      pointerId:e.pointerId
    };
  },true);

  scroll.addEventListener('pointerup',e=>{
    if(!start || start.pointerId!==e.pointerId){
      start=null;
      return;
    }

    const dx=e.clientX-start.x;
    const dy=e.clientY-start.y;
    const moved=Math.hypot(dx,dy);
    const cell=findHighlightCellAtPoint(stripSelector,cellSelector,e.clientX,e.clientY);
    const id=cell?.getAttribute(idAttr);

    if(cell && id===start.id && moved<10){
      if(Date.now()-lastHighlightPointerHandledAt<450){
        start=null;
        return;
      }
      e.preventDefault();
      e.stopImmediatePropagation();
      lastHighlightPointerHandledAt=Date.now();
      openFn(id);
    }
    start=null;
  },true);

  scroll.addEventListener('pointercancel',()=>{start=null;},true);

  /* suppress the synthetic click that follows a handled pointerup */
  scroll.addEventListener('click',e=>{
    if(Date.now()-lastHighlightPointerHandledAt>450)return;
    const cell=findHighlightCellAtPoint(stripSelector,cellSelector,e.clientX,e.clientY);
    if(!cell)return;
    e.preventDefault();
    e.stopImmediatePropagation();
  },true);
}

function bindHighlightGeometryFallback(){
  bindOneHighlightPointerFallback(
    document.querySelector('.user-profile-scroll'),
    '#userHighlightStrip',
    '[data-highlight-id]',
    'data-highlight-id',
    handleUserHighlightTap,
    'highlightPointerBound'
  );

  bindOneHighlightPointerFallback(
    document.querySelector('.char-profile-scroll'),
    '#charHighlightStrip',
    '[data-char-highlight-id]',
    'data-char-highlight-id',
    handleCharHighlightTap,
    'highlightPointerBound'
  );
}

bindHighlightGeometryFallback();

/* v5.0.8: normal tap keeps opening the archived Highlight; long-press / context menu
   is a direct secondary edit path for name, cover and purpose description. */
function bindHighlightLongPressEdit(stripSelector,itemSelector,idAttr,editFn){
  const strip=document.querySelector(stripSelector);
  if(!strip || strip.dataset.longPressEditBound)return;
  strip.dataset.longPressEditBound='1';
  let timer=null,start=null;
  const clear=()=>{if(timer)clearTimeout(timer);timer=null;start=null;};
  strip.addEventListener('pointerdown',event=>{
    const item=event.target.closest(itemSelector);
    const id=item?.getAttribute(idAttr);
    if(!item || !id || id==='__new')return;
    start={x:event.clientX,y:event.clientY,id,pointerId:event.pointerId};
    timer=setTimeout(()=>{
      if(!start)return;
      lastHighlightPointerHandledAt=Date.now();
      editFn(start.id);
      clear();
    },520);
  },true);
  strip.addEventListener('pointermove',event=>{
    if(start && Math.hypot(event.clientX-start.x,event.clientY-start.y)>10)clear();
  },true);
  strip.addEventListener('pointerup',clear,true);
  strip.addEventListener('pointercancel',clear,true);
  strip.addEventListener('contextmenu',event=>{
    const item=event.target.closest(itemSelector);
    const id=item?.getAttribute(idAttr);
    if(!item || !id || id==='__new')return;
    event.preventDefault();
    event.stopPropagation();
    editFn(id);
  });
}
/* v5.0.9: no long-press edit binding. Bound Highlights open Story viewer; edit lives on viewer ⋯. */

