/* v5.0.8: geometry fallback for Roche WebView.
   It resolves the tab by coordinates at the route capture layer, so a transparent sibling
   can no longer swallow the four Profile tabs. */
function activateCharProfileTab(tabName){
  if(!currentCharProfile || !tabName)return false;
  const profile=getCharProfileData(currentCharProfile);
  if(tabName==='album' && profile?.profileType!=='roche')return false;
  if(!['posts','reels','album','board'].includes(tabName))return false;
  charProfileState.activeTab=tabName;
  renderCharProfileContent();
  return true;
}
function getCharTabAtPoint(x,y){
  const wrap=document.querySelector('#routeCharProfile .char-profile-tabs');
  if(!wrap)return null;
  const r=wrap.getBoundingClientRect();
  if(x<r.left || x>r.right || y<r.top || y>r.bottom)return null;
  const profile=currentCharProfile?getCharProfileData(currentCharProfile):null;
  const names=profile?.profileType==='roche'?['posts','reels','album','board']:['posts','reels','board'];
  const unit=Math.max(1,r.width/names.length);
  const idx=Math.max(0,Math.min(names.length-1,Math.floor((x-r.left)/unit)));
  const tabName=names[idx];
  return wrap.querySelector(`.char-tab[data-char-tab="${tabName}"]`);
}
(function bindCharProfileTabGeometryFallback(){
  const route=document.getElementById('routeCharProfile');
  if(!route || route.dataset.tabGeometryBound)return;
  route.dataset.tabGeometryBound='1';
  let down=null;
  route.addEventListener('pointerdown',event=>{
    const btn=getCharTabAtPoint(event.clientX,event.clientY);
    down=btn?{pointerId:event.pointerId,x:event.clientX,y:event.clientY,tab:btn.dataset.charTab}:null;
  },true);
  route.addEventListener('pointerup',event=>{
    if(!down || down.pointerId!==event.pointerId){down=null;return;}
    const moved=Math.hypot(event.clientX-down.x,event.clientY-down.y);
    const btn=getCharTabAtPoint(event.clientX,event.clientY);
    const tab=btn?.dataset.charTab;
    if(moved<12 && tab && tab===down.tab && activateCharProfileTab(tab)){
      event.preventDefault();
      event.stopImmediatePropagation();
    }
    down=null;
  },true);
  route.addEventListener('pointercancel',()=>{down=null;},true);
})();

