function hardEnableHighlightTextarea(id){
  const el=document.getElementById(id);
  if(!el)return;
  el.disabled=false;
  el.readOnly=false;
  el.removeAttribute('readonly');
  el.removeAttribute('disabled');
  if(el.dataset.highlightInputGuardBound)return;
  el.dataset.highlightInputGuardBound='1';
  ['pointerdown','mousedown','touchstart','click'].forEach(type=>{
    el.addEventListener(type,event=>event.stopPropagation(),{passive:type==='touchstart'});
  });
}
